Object.assign(window.TEM8_DICTIONARY, {"tidying":{"oxford":{"phon":"ˈtaɪdi","pos":"adjective","senses":[{"en":"( especially BrE ) arranged neatly and with everything in order","cn":"整洁的；整齐的；井然有序的；井井有条的"},{"en":"( especially BrE ) keeping things neat and in order","cn":"爱整洁的；爱整齐的"}]},"media":{"uk":"media/uk/tidy__gb_1.mp3","us":"media/us/tidy__us_1.mp3"}},"timing":{"media":{"uk":"media/uk/timing__gb_1.mp3","us":"media/us/timing__us_1.mp3"},"oxford":{"phon":"ˈtaɪmɪŋ","pos":"noun","senses":[{"en":"the act of choosing when something happens; a particular point or period of time when something happens or is planned","cn":"定时；时间的选择；（事情发生或计划安排的）特定时间","g":"[uncountable, countable]","ex":{"en":"The timing of the decision was a complete surprise.","cn":"选择那个时间作决定，完全出人意料。"}},{"en":"the skill of doing something at exactly the right time","cn":"时机的掌握；火候的把握","g":"[uncountable]","ex":{"en":"an actor with a great sense of comic timing","cn":"一位深谙把握时机引人发笑的演员"}},{"en":"the repeated rhythm of something; the skill of producing this","cn":"节奏；掌握节奏的技巧","g":"[uncountable]","ex":{"en":"She played the piano confidently but her timing was not good.","cn":"她钢琴弹得很自信，但是节奏掌握得不好。"}},{"en":"the rate at which an electric spark is produced in a vehicle’s engine in order to make it work","cn":"（汽车发动机的）点火时间控制","g":"[uncountable]","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"时机掌握;时间选择","en":"Timing is the skill or action of judging the right moment in a situation or activity at which to do something.","ex":{"en":"His photo is a wonderful happy moment caught with perfect timing","cn":"他拍的照片时机掌握完美，记录下了动人的快乐瞬间。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"时间安排","en":"Timing is used to refer to the time at which something happens or is planned to happen, or to the length of time that something takes.","ex":{"en":"The timing of the minister's visit, however, could somewhat detract from the goodwill it's supposed to generate.","cn":"但是，部长访问的时间安排不当，可能会使访问的善意不能得到有效传达。"}}]},"examples":[{"en":"She played the piano confidently but her timing was not good.","cn":"她钢琴弹得很自信，但是节奏掌握得不好。"},{"en":"Your timing is perfect. I was just about to call you.","cn":"你来得正是时候。我刚想要给你打电话。"}]},"tickets":{"oxford":{"phon":"ˈtɪkɪt","pos":"noun","senses":[{"en":"a printed piece of paper that gives you the right to travel on a particular bus, train, etc. or to go into a theatre, etc.","cn":"票；券；车票；戏票；入场券"},{"en":"a printed piece of paper with a number or numbers on it, that you buy in order to have the chance of winning a prize if the number or numbers are later chosen","cn":"奖券；彩票"}]},"media":{"img":["media/pic/label_comp.jpg","media/thumb/ticket.jpg"],"uk":"media/uk/ticket__gb_1.mp3","us":"media/us/ticket__us_1.mp3"}},"till":{"media":{"uk":"media/uk/till__gb_1.mp3","us":"media/us/till__us_1.mp3"},"oxford":{"phon":"tɪl","pos":"conjunction, preposition","senses":[{"en":"until","cn":"到…时；直到…为止","ex":{"en":"We're open till 6 o'clock.","cn":"我们营业到 6 点钟。"}},{"en":"a machine used in shops, restaurants, etc. for keeping money in, and that shows and records the amount of money received for each thing that is sold","cn":"现金收入记录机；现金出纳机","lab":"British English","pos":"noun"},{"en":"the place where you pay for goods in a large shop","cn":"（大商店中的）交款处，收银台","lab":"British English, informal，，","ex":{"en":"Please pay at the till.","cn":"请在交款处付款。"},"pos":"noun"},{"en":"the drawer where the money is put in a cash register","cn":"（现金出纳机的）放钱的抽屉","lab":"especially North American English","pos":"noun"},{"en":"to prepare and use land for growing crops","cn":"耕作；犁地","pos":"verb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"(常于口语与非正式书面语中代替 until)","en":"In spoken English and informal written English, till is often used instead of until .","ex":{"en":"They had to wait till Monday to ring the bank manager","cn":"他们必须等到周一才能给银行经理打电话。"}},{"pos":"N-COUNT 可数名词","cn":"(商店等处的)现金出纳机，收银机","en":"In a shop or other place of business, a till is a counter or cash register where money is kept, and where customers pay for what they have bought.","ex":{"en":"...long queues at tills that make customers angry.","cn":"收银台前令顾客恼火的长队"}},{"pos":"N-COUNT 可数名词","cn":"(收银机中的)钱柜，放钱的抽屉","en":"A till is the drawer of a cash register, in which the money is kept.","ex":{"en":"He checked the register. There was money in the till.","cn":"他查看了一下收银机的抽屉，里面有钱。"}},{"pos":"VERB 动词","cn":"耕，犁(地)","en":"When people till land, they prepare the earth and work on it in order to grow crops.","ex":{"en":"Workers were singing as they tilled the rice paddy fields.","cn":"劳动者们一边耕犁稻田一边唱歌。"}}]},"examples":[{"en":"Just wait till you see it. It's great.","cn":"你就等着直到看见它吧。好看极了。"},{"en":"Can't you wait till we get home?","cn":"难道你就不能等我们回到家吗？"}]},"tides":{"oxford":{"phon":"taɪd","pos":"noun","senses":[{"en":"a regular rise and fall in the level of the sea, caused by the pull of the moon and sun; the flow of water that happens as the sea rises and falls","cn":"潮；潮汐；潮水"},{"en":"the direction in which the opinion of a large number of people seems to be moving","cn":"潮流；趋势；动向"}]},"media":{"uk":"media/uk/tide__gb_1.mp3","us":"media/us/tide__us_1.mp3"}},"tiger":{"media":{"uk":"media/uk/tiger__gb_1.mp3","us":"media/us/tiger__us_1.mp3","img":["media/ldoce/img/tiger.jpg"]},"oxford":{"phon":"ˈtaɪɡə(r)","pos":"noun","senses":[{"en":"a large wild animal of the cat family that has orange fur with black stripes (= narrow lines) and lives in parts of Asia","cn":"虎；老虎","ex":{"en":"She fought like a tiger to be able to keep her children.","cn":"她勇猛搏斗，以便能保住她的孩子。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"虎;老虎","en":"A tiger is a large fierce animal belonging to the cat family. Tigers are orange with black stripes."}]},"examples":[{"en":"She fought like a tiger to be able to keep her children.","cn":"她勇猛搏斗，以便能保住她的孩子。"}]},"tide":{"media":{"uk":"media/uk/tide__gb_1.mp3","us":"media/us/tide__us_1.mp3"},"oxford":{"phon":"taɪd","pos":"noun","senses":[{"en":"a regular rise and fall in the level of the sea, caused by the pull of the moon and sun; the flow of water that happens as the sea rises and falls","cn":"潮；潮汐；潮水","g":"[countable, uncountable]","ex":{"en":"the ebb and flow of the tide","cn":"海潮的涨落"}},{"en":"the direction in which the opinion of a large number of people seems to be moving","cn":"潮流；趋势；动向","g":"[countable, usually singular]","ex":{"en":"It takes courage to speak out against the tide of opinion.","cn":"跟舆论趋向唱反调需要勇气。"}},{"en":"a large amount of something unpleasant that is increasing and is difficult to control","cn":"（难以控制的）恶潮，怒潮","g":"[countable, usually singular]","ex":{"en":"There is anxiety about the rising tide of crime.","cn":"犯罪率日益增长令人忧虑。"}},{"en":"a feeling that you suddenly have that gets stronger and stronger","cn":"高涨的情绪","g":"[singular]","ex":{"en":"A tide of rage surged through her.","cn":"一股怒火燃遍她的全身。"}},{"en":"a time or season of the year","cn":"时节；季节","g":"[singular]","lab":"old use","ex":{"en":"Christmastide","cn":"圣诞节节期"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"潮;潮水;潮汐","en":"The tide is the regular change in the level of the sea on the shore.","ex":{"en":"The tide was at its highest","cn":"潮水正处于最高位。"}},{"pos":"N-COUNT 可数名词","cn":"(不断冲刷海岸的)潮水，潮汐","en":"A tide is a current in the sea that is caused by the regular and continuous movement of large areas of water towards and away from the shore.","ex":{"en":"Roman vessels used to sail with the tide from Boulogne to Richborough.","cn":"罗马的船只过去经常乘着潮汐从布洛涅航行到里奇伯勒。"}},{"pos":"N-SING 单数名词","cn":"(观点等的)潮流，趋势","en":"The tide of opinion, for example, is what the majority of people think at a particular time.","ex":{"en":"The tide of opinion seems overwhelmingly in his favour.","cn":"绝大多数人的观点看来是一边倒地支持他的。"}},{"pos":"N-SING 单数名词","cn":"(无法抗拒的)潮流，浪潮","en":"People sometimes refer to events or forces that are difficult or impossible to control as the tide of history, for example.","ex":{"en":"They talked of reversing the tide of history","cn":"他们谈到扭转历史潮流。"}},{"pos":"N-SING 单数名词","cn":"(尤指不好的)浪潮，势头","en":"You can talk about a tide of something, especially something which is unpleasant, when there is a large and increasing amount of it.","ex":{"en":"...an ever increasing tide of crime","cn":"不断高涨的犯罪浪潮"}},{"pos":"","cn":"","en":"相关词组：tide over"}]},"examples":[{"en":"Can you lend me some money to tide me over until I get paid?","cn":"你能借些钱给我帮我凑合到发薪日吗？"},{"en":"It takes courage to speak out against the tide of opinion.","cn":"跟舆论趋向唱反调需要勇气。"}]},"tidewater":{"media":{"uk":"media/uk/tidewater__gb_1.mp3","us":"media/us/tidewater__us_1.mp3"},"oxford":{"phon":"ˈtaɪdwɔːtə(r)","pos":"noun","senses":[{"en":"an area of land at or near the coast","cn":"滨海地区；沿海低地","g":"[countable]","lab":"North American English"},{"en":"water that is brought by the tide","cn":"潮水","g":"[uncountable, countable]"}]}},"tiredness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling that you want to sleep or rest","cn":""},{"en":"extremely tired","cn":""}]},"examples":[{"en":"I’m so tired I could sleep for a week.","cn":"","src":"ld"},{"en":"He was too tired to argue.","cn":"","src":"ld"}],"media":{"uk":"media/uk/tiredness__gb_1.mp3","us":"media/us/tiredness__us_1.mp3"},"oxford":{"phon":"ˈtaɪədnəs","pos":"noun","senses":[{"en":"the feeling that you would like to sleep or rest","cn":"疲倦的；疲劳的；困倦的","ex":{"en":"She pleaded tiredness and went to bed early.","cn":"她借口太累了，就早早上床睡觉了。"}}]}},"tissues":{"oxford":{"phon":"ˈtɪʃuː","pos":"noun","senses":[{"en":"a collection of cells that form the different parts of humans, animals and plants （","cn":"人、动植物细胞的）组织"},{"en":"a piece of soft paper that absorbs liquids, used especially as a handkerchief （","cn":"尤指用作手帕的）纸巾，手巾纸"}]}},"timid":{"media":{"uk":"media/uk/timid__gb_1.mp3","us":"media/us/timid__us_1.mp3"},"oxford":{"phon":"ˈtɪmɪd","pos":"adjective","senses":[{"en":"shy and nervous; not brave","cn":"羞怯的；胆怯的；缺乏勇气的","ex":{"en":"He stopped in the doorway, too timid to go in.","cn":"他在门口停住了脚步，不好意思进去。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"胆小的;害羞的;缺乏自信的","en":"Timid people are shy, nervous, and have no courage or confidence in themselves.","ex":{"en":"A timid child, Isabella had learned obedience at an early age.","cn":"伊莎贝拉是一个羞怯的孩子，很小就学会了顺从。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"犹豫不决的;瞻前顾后的","en":"If you describe someone's attitudes or actions as timid, you are criticizing them for being too cautious or slow to act, because they are nervous about the possible consequences of their actions.","ex":{"en":"The President's critics say he has been too timid in responding to changing international developments","cn":"批评总统的人认为他在应对风云变幻的国际局势时过于瞻前顾后。"}}]},"examples":[{"en":"He stopped in the doorway, too timid to go in.","cn":"他在门口停住了脚步，不好意思进去。"},{"en":"They've been rather timid in the changes they've made (= they've been afraid to make any big changes).","cn":"他们对所进行的变革一直小心翼翼。"}]},"tired":{"media":{"uk":"media/uk/tired__gb_1.mp3","us":"media/us/tired__us_1.mp3"},"oxford":{"phon":"ˈtaɪəd","pos":"adjective","senses":[{"en":"feeling that you would like to sleep or rest; needing rest","cn":"疲倦的；疲劳的；困倦的","ex":{"en":"to be/look/feel tired","cn":"感到／显得／觉得疲惫"}},{"en":"feeling that you have had enough of somebody/something because you no longer find them/it interesting or because they make you angry or unhappy","cn":"厌倦；厌烦","ex":{"en":"I'm sick and tired of all the arguments.","cn":"我对所有这些争论烦透了。"}},{"en":"boring because it is too familiar or has been used too much","cn":"陈旧的；陈腐的；陈词滥调的","ex":{"en":"He always comes out with the same tired old jokes.","cn":"他总是讲些千篇一律老掉牙的笑话。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"疲劳的；累的","en":"If you are tired, you feel that you want to rest or sleep.","ex":{"en":"Michael is tired and he has to rest after his long trip.","cn":"迈克尔累了，他在长途旅行以后必须休息。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(身体部位)显出倦意的，感到疲乏的","en":"You can describe a part of your body as tired if it looks or feels as if you need to rest it or to sleep.","ex":{"en":"Cucumber is good for soothing tired eyes…","cn":"黄瓜有助于舒缓眼部疲劳。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"厌烦的;厌倦的","en":"If you are tired of something, you do not want it to continue because you are bored of it or unhappy with it.","ex":{"en":"I am tired of all the speculation","cn":"我厌烦了所有的推测。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"陈旧的;陈腐的","en":"If you describe something as tired, you are critical of it because you have heard it or seen it many times.","ex":{"en":"I didn't want to hear another one of his tired excuses","cn":"我不想听他的又一个老掉牙的借口。"}}]},"examples":[{"en":"He always comes out with the same tired old jokes.","cn":"他总是讲些千篇一律老掉牙的笑话。"},{"en":"They were cold, hungry and tired out (= very tired).","cn":"他们又冷又饿，疲惫不堪。"}]},"ticket":{"media":{"img":["media/pic/label_comp.jpg","media/thumb/ticket.jpg"],"uk":"media/uk/ticket__gb_1.mp3","us":"media/us/ticket__us_1.mp3"},"oxford":{"phon":"ˈtɪkɪt","pos":"noun","senses":[{"en":"a printed piece of paper, or a message or image received on your phone or computer, that gives you the right to travel on a particular bus, train, etc. or to go into a theatre, etc.","cn":"（纸质或电子）票，券，车票，戏票，入场券","lab":"figurative","ex":{"en":"a plane/bus/train ticket","cn":"飞机票；公共汽车票；火车票"}},{"en":"a printed piece of paper with a number or numbers on it, that you buy in order to have the chance of winning a prize if the number or numbers are later chosen","cn":"奖券；彩票","ex":{"en":"a lottery/raffle ticket","cn":"彩票"}},{"en":"a label that is attached to something in a shop giving details of its price, size, etc.","cn":"（商店中标明货物价格、尺码等的）标签"},{"en":"an official notice that orders you to pay a fine because you have done something illegal while driving or parking your car","cn":"（交通违章）通知单，罚款单","ex":{"en":"a speeding ticket","cn":"超速驾驶罚款单"}},{"en":"a list of candidates that are supported by a particular political party in an election","cn":"（政党在选举中所支持的）候选人名单","g":"[usually singular]","lab":"especially North American English","ex":{"en":"She ran for office on the Democratic ticket.","cn":"她作为民主党的候选人参加竞选。"}},{"en":"a request for a problem to be fixed that is entered into a system that manages such requests","cn":"故障单，工单","ex":{"en":"Open a ticket with the Help Desk.","cn":"通过服务台开具票证。"}},{"en":"to produce and sell tickets for an event, a trip, etc.; to give somebody a ticket","cn":"售票；给…门票；送票","lab":"specialist","ex":{"en":"Passengers can now be ticketed electronically.","cn":"旅客现在可以电子购票。"},"pos":"verb"},{"en":"to give somebody an official notice that orders them to pay a fine because they have done something illegal while driving or parking a car","cn":"发出交通违章通知单","lab":"especially North American English","ex":{"en":"Park illegally, and you're likely to be ticketed.","cn":"违章停车就可能收到罚款单。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(剧院、运动场、表演等的)入场券，门票，票","en":"A ticket is a small, official piece of paper or card which shows that you have paid to enter a place such as a theatre or a sports ground, or shows that you have paid for a journey.","ex":{"en":"I queued for two hours to get a ticket to see the football game","cn":"我排了两个小时的队，就是为了买张足球赛的票。"}},{"pos":"N-COUNT 可数名词","cn":"(交通)罚款通知单，违章通知单","en":"A ticket is an official piece of paper which orders you to pay a fine or to appear in court because you have committed a driving or parking offence.","ex":{"en":"I want to know at what point I break the speed limit and get a ticket.","cn":"我想知道我是在什么地方超速而受到处罚的。"}},{"pos":"N-COUNT 可数名词","cn":"兑奖券;彩票","en":"A ticket for a game of chance such as a raffle or a lottery is a piece of paper with a number on it. If the number on your ticket matches the number chosen, you win a prize.","ex":{"en":"She bought a lottery ticket and won more than $33 million.","cn":"她买了张彩票，中了3,300多万美元。"}},{"pos":"N-SING 单数名词","cn":"(竞选时所代表的)政党;(竞选时所支持的)纲领，政见","en":"The particular ticket on which a person fights an election is the party they represent or the policies they support.","ex":{"en":"He first ran for president on a far-left ticket","cn":"他第一次代表极左政党参加总统竞选。"}},{"pos":"N-COUNT 可数名词","cn":"(政党、团体的)候选人名单","en":"A ticket is the list of candidates who are representing a particular political party or group in an election.","ex":{"en":"He plans to remain on the Republican ticket for the November election.","cn":"他计划继续代表共和党参加 11 月份的选举。"}},{"pos":"PHRASE 短语","cn":"正是所需要的东西","en":"If you say that something is just the ticket, you mean that it is exactly what is needed.","ex":{"en":"Young kids need all the energy and protein they can get and whole milk is just the ticket.","cn":"儿童需要摄入足量能量和蛋白质，而全脂牛奶正好能满足这一需求。"}}]},"examples":[{"en":"( figurative ) She hoped that getting this job would finally be her ticket to success.","cn":"她希望得到这份工作终将会使她踏上成功之途。"},{"en":"Tickets are available from the Arts Centre at £5.00.","cn":"艺术中心有票，每张 5 英镑。"}]},"tight":{"media":{"uk":"media/uk/tight__gb_1.mp3","us":"media/us/tight__us_1.mp3"},"oxford":{"phon":"taɪt","pos":"adjective","senses":[{"en":"held or fixed in position securely; difficult to move, open or separate","cn":"牢固的；紧的；不松动的；难解开的","sc":"firm","ex":{"en":"He kept a tight grip on her arm.","cn":"他紧紧握住她的胳膊。"}},{"en":"fitting closely to your body and sometimes uncomfortable","cn":"紧身的；紧贴的","sc":"clothes","ex":{"en":"She was wearing a tight pair of jeans.","cn":"她穿着一条紧身牛仔裤。"}},{"en":"difficult to manage with because there is not enough","cn":"紧的；拮据的；不宽裕的","sc":"money/time","ex":{"en":"We have a very tight budget.","cn":"我们的预算很紧。"}},{"en":"very strict and hard to resist, avoid, etc.","cn":"严密的；严格的；严厉的","sc":"control","ex":{"en":"to keep tight control over something","cn":"对某事严加控制"}},{"en":"stretched or pulled so that it cannot stretch much further","cn":"拉紧的；绷紧的","sc":"stretched","ex":{"en":"The rope was stretched tight.","cn":"这绳子拉得很紧。"}},{"en":"with things or people packed closely together, leaving little space between them","cn":"装紧的；密集的；挤满的","g":"[usually before noun]","sc":"close together","ex":{"en":"There was a tight group of people around the speaker.","cn":"演讲人周围严严实实地挤了一群人。"}},{"en":"looking or sounding anxious, upset or angry","cn":"显得紧张的；忐忑不安的；生气的","sc":"expression/voice","ex":{"en":"‘I'm sorry,’ she said, with a tight smile.","cn":"“对不起。”她勉强一笑说。"}},{"en":"feeling painful or uncomfortable because of illness or emotion","cn":"（由于疾病或情感）疼痛的，不适的，憋气的","sc":"part of body","ex":{"en":"He complained of having a tight chest.","cn":"他主诉胸部憋闷。"}},{"en":"having a close relationship with somebody else or with other people","cn":"亲密的；紧密的；密切的","sc":"relationship","ex":{"en":"It was a tight community and newcomers were not welcome.","cn":"这个社群内部很紧密，不太接纳新来的人。"}},{"en":"curving suddenly rather than gradually","cn":"急转的；陡的","sc":"bend/curve","ex":{"en":"The driver slowed down at a tight bend in the road.","cn":"驾驶员在道路急转弯处慢了下来。"}},{"en":"with runners, teams, etc. that seem to be equally good","cn":"势均力敌的；不相上下的；旗鼓相当的","sc":"contest/race","ex":{"en":"a tight race","cn":"势均力敌的赛跑"}},{"en":"not wanting to spend much money; not generous","cn":"小气的；吝啬的；不大方的","lab":"informal, disapproving，，","sc":"not generous","ex":{"en":"He's very tight with his money.","cn":"他花钱很抠门儿。"}},{"en":"drunk","cn":"喝醉","g":"[not usually before noun]","lab":"old-fashioned, informal，，","sc":"drunk"},{"en":"not allowing the substance mentioned to enter","cn":"不漏…的；不透…的；防…的","sc":"-tight","ex":{"en":"measures to make your home weathertight","cn":"使你家防风雨的措施"}},{"en":"closely and strongly; tightly","cn":"紧紧地；牢固地","ex":{"en":"Hold tight!","cn":"抓紧了！"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服或鞋)紧身的，紧贴的","en":"Tight clothes or shoes are rather small and fit closely to your body.","ex":{"en":"She walked off the plane in a miniskirt and tight top","cn":"她身穿迷你裙和紧身上衣走下了飞机。"}},{"pos":"ADV-GRADED 副词","cn":"牢牢地;紧紧地","en":"If you hold someone or something tight, you hold them firmly and securely.","ex":{"en":"She just fell into my arms, clutching me tight for a moment","cn":"她正好跌进我的怀里，一时间紧紧地抓着我。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(控制或规则)严格的，严厉的","en":"Tight controls or rules are very strict.","ex":{"en":"The measures include tight control of media coverage","cn":"那些措施包括对媒体报道的严格管制。"}},{"pos":"ADV-GRADED 副词","cn":"紧紧地;密不透风地;滴水不漏地","en":"Something that is shut tight is shut very firmly.","ex":{"en":"The baby lay on his back with his eyes closed tight","cn":"那个婴儿仰面躺着，两眼紧闭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(皮肤、布、线)拉紧的，绷紧的","en":"Skin, cloth, or string that is tight is stretched or pulled so that it is smooth or straight.","ex":{"en":"My skin feels tight and lacking in moisture","cn":"我的皮肤感觉紧巴巴的，缺少水分。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧密的;密集的;装得满满的","en":"Tight is used to describe a group of things or an amount of something that is closely packed together.","ex":{"en":"She curled up in a tight ball, with her knees tucked up at her chin","cn":"她蜷缩成一团，膝盖抵着下巴。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(身体局部)不舒服的，憋闷的","en":"If a part of your body is tight, it feels rather uncomfortable and painful, for example because you are ill, anxious, or angry.","ex":{"en":"It is better to stretch the tight muscles first","cn":"最好先伸展一下僵硬的肌肉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"关系紧密的;亲密的","en":"A tight group of people is one whose members are closely linked by beliefs, feelings, or interests.","ex":{"en":"We're a tight group, so we do keep in touch.","cn":"我们关系很铁，所以的确保持着联系。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(弯道、拐角)急转的，陡转的","en":"A tight bend or corner is one that changes direction very quickly so that you cannot see very far round it.","ex":{"en":"They collided on a tight bend and both cars were extensively damaged.","cn":"他们在一个急转弯处相撞，两辆车均严重受损。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(日程、预算)紧张的，回旋余地不大的","en":"A tight schedule or budget allows very little time or money for unexpected events or expenses.","ex":{"en":"It's difficult to cram everything into a tight schedule","cn":"日程紧，很难把所有事情都安排进去。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(比赛双方)比分接近的，不相上下的，势均力敌的","en":"A tight contest is one where none of the competitors has a clear advantage or looks likely to win, so that it is difficult to say who the winner will be.","ex":{"en":"It was a very tight match","cn":"参赛双方不分伯仲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"小气的;抠门儿的;吝啬的","en":"If you say that someone is tight, you disapprove of them because they are unwilling to spend their money.","ex":{"en":"What about getting new ones — Are you so tight you won't even spend three roubles?","cn":"买些新的怎样——你就小气到连3个卢布也不肯掏吗？"}},{"pos":"PHRASE 短语","cn":"处境困难;境况不好","en":"If you are in a tight corner or in a tight spot, you are in a difficult situation.","ex":{"en":"That puts the president in a tight spot if the vote is not a resounding 'yes'","cn":"如果投票结果不是一个响亮的“是”，总统的处境就不妙了。"}},{"pos":"CONVENTION 惯用语","cn":"好好睡一觉","en":"You can say 'sleep tight' to someone when they are going to bed as an affectionate way of saying that you hope they will sleep well.","ex":{"en":"Good night, Davey. Sleep tight.","cn":"晚安，戴维。睡个好觉。"}},{"pos":"","cn":"","en":"to keep a tight rein on→see: ; to sit tight→see: ;"}]},"examples":[{"en":"Her throat felt tight, just looking at her baby.","cn":"她喉咙哽咽得说不出话来，只是看着她的婴儿。"},{"en":"We need tighter security at the airport.","cn":"我们需要在机场实行更加严密的安全措施。"}]},"tick":{"media":{"img":["media/pic/arachnids_comp.jpg","media/thumb/tick.jpg"],"uk":"media/uk/tick__gb_1.mp3","us":"media/us/tick__us_1.mp3"},"oxford":{"phon":"tɪk","pos":"verb","senses":[{"en":"to make short, light, regular repeated sounds to mark time passing","cn":"发出滴答声；滴答地走时","g":"[intransitive]","ex":{"en":"In the silence we could hear the clock ticking.","cn":"寂静中，我们能听到钟表滴答作响。"}},{"en":"to put a mark (✓) next to an item on a list, an answer, etc.","cn":"标记号；打上钩；打对号","g":"[transitive]","lab":"British English","ex":{"en":"Please tick the appropriate box.","cn":"请在适合的方框内打钩。"}},{"en":"a mark (✓) put next to a sum or an item on a list, usually to show that it has been checked or done or is correct","cn":"核对号；对号；钩号","g":"[countable]","lab":"British English","ex":{"en":"Put a tick in the appropriate box if you would like further information about any of our products.","cn":"如想进一步了解我们任何产品的情况，请在适当的方框内打钩。"},"pos":"noun"},{"en":"a very small creature that bites humans and animals and drinks their blood. There are several types of tick, some of which can carry diseases.","cn":"蜱，壁虱，扁虱（吸血寄生虫，有些种类能传播疾病）","g":"[countable]","ex":{"en":"a tick bite","cn":"蜱叮咬之处"},"pos":"noun"},{"en":"a short, light, regularly repeated sound, especially that of a clock or watch","cn":"（尤指钟表的）滴答声","g":"[uncountable]","ex":{"en":"The only sound was the soft tick of the clock.","cn":"唯一的响声是钟表轻轻的滴答声。"},"pos":"noun"},{"en":"a moment","cn":"一会儿；一瞬间；一刹那；片刻","g":"[countable]","lab":"British English, informal，，","ex":{"en":"Hang on a tick!","cn":"等一会儿，别挂断电话！"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钩号(符号为√)","en":"A tick is a written mark like a V: ✓. It is used to show that something is correct or has been selected or dealt with.","ex":{"en":"His exercise books were full of well deserved red ticks","cn":"他的练习本上尽是些红钩钩，都是他应得的。"}},{"pos":"VERB 动词","cn":"在(纸)上打钩","en":"If you tick something that is written on a piece of paper, you put a tick next to it.","ex":{"en":"Please tick this box if you do not wish to receive such mailings","cn":"如果你不想收到此类邮件，请在这个方框里打钩。"}},{"pos":"VERB 动词","cn":"(钟表)嘀嗒作响，发出嘀嗒声","en":"When a clock or watch ticks, it makes a regular series of short sounds as it works.","ex":{"en":"A wind-up clock ticked busily from the kitchen counter.","cn":"一只上了弦的钟在厨房的案子上嘀嗒响个不停。"}},{"pos":"N-COUNT 可数名词","cn":"(钟表的)嘀嗒声","en":"The tick of a clock or watch is the series of short sounds it makes when it is working, or one of those sounds.","ex":{"en":"He sat listening to the tick of the grandfather clock.","cn":"他坐在那儿，听着落地式大摆钟嘀嗒作响。"}},{"pos":"N-COUNT 可数名词","cn":"一瞬间;一刹那","en":"You can use tick to refer to a very short period of time.","ex":{"en":"Just hang on a tick, we may be able to help","cn":"稍等一会儿，我们或许能帮上忙。"}},{"pos":"VERB 动词","cn":"(某人的思想、愿望或情感使其)做出…举动;有…的行为","en":"If you talk about what makes someone tick, you are talking about the beliefs, wishes, and feelings that make them behave in the way that they do.","ex":{"en":"He wanted to find out what made them tick","cn":"他想搞清楚他们为什么会那样。"}},{"pos":"N-COUNT 可数名词","cn":"蜱;壁虱","en":"A tick is a small creature which lives on the bodies of people or animals and uses their blood as food.","ex":{"en":"...chemicals that destroy ticks and mites","cn":"杀灭蜱和螨虫的化学品"}},{"pos":"","cn":"","en":"相关词组：tick away tick by tick off tick on tick over"}]},"examples":[{"en":"Put a tick in the appropriate box if you would like further information about any of our products.","cn":"如想进一步了解我们任何产品的情况，请在适当的方框内打钩。"},{"en":"While we waited the taxi's meter kept ticking away.","cn":"我们等候时，出租汽车的计程器一直在滴答滴答地走着。"}]},"tickle":{"media":{"uk":"media/uk/tickle__gb_1.mp3","us":"media/us/tickle__us_1.mp3"},"oxford":{"phon":"ˈtɪkl","pos":"verb","senses":[{"en":"to move your fingers on a sensitive part of somebody’s body in a way that makes them laugh","cn":"呵痒；胳肢","g":"[transitive, intransitive]","ex":{"en":"The bigger girls used to chase me and tickle me.","cn":"比我高大的女孩过去总是追赶着胳肢我。"}},{"en":"to produce a slightly uncomfortable feeling in a sensitive part of the body; to have a feeling like this","cn":"（使）发痒","g":"[transitive, intransitive]","ex":{"en":"His beard was tickling her cheek.","cn":"他的胡须扎得她的面颊痒痒的。"}},{"en":"to please and interest somebody","cn":"逗乐；使高兴；使感兴趣；使满足","g":"[transitive]","ex":{"en":"to tickle somebody’s imagination","cn":"满足某人的想象力"}},{"en":"an act of tickling somebody","cn":"呵痒；胳肢","ex":{"en":"She gave the child a little tickle.","cn":"她轻轻地胳肢孩子。"},"pos":"noun"},{"en":"a slightly uncomfortable feeling in a part of your body","cn":"痒；痒感","ex":{"en":"to have a tickle in your throat (= that makes you want to cough)","cn":"喉咙里发痒"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"胳肢;使笑个不停","en":"When you tickle someone, you move your fingers lightly over a sensitive part of their body, often in order to make them laugh.","ex":{"en":"I was tickling him, and he was laughing and giggling.","cn":"我在胳肢他，他哈哈哈、咯咯咯地笑个不停。"}},{"pos":"VERB 动词","cn":"（使）发痒;（使）难受","en":"If something tickles you or tickles, it causes an irritating feeling by lightly touching a part of your body.","ex":{"en":"...a yellow hat with a great feather that tickled her ear","cn":"上面有根大羽毛、搞得她耳朵很痒的一顶黄色礼帽"}},{"pos":"VERB 动词","cn":"使开心;使高兴","en":"If a fact or a situation tickles you, it amuses you or gives you pleasure.","ex":{"en":"It tickles me to see him riled","cn":"看见他生气我就觉得忍俊不禁。"}},{"pos":"PHRASE 短语","cn":"非常开心","en":"If you are tickled pink, you are extremely pleased about something.","ex":{"en":"'I'm tickled pink,' said Jimmy after his wife gave birth.","cn":"“我太开心了，”吉米在妻子分娩后说。"}}]},"examples":[{"en":"The bigger girls used to chase me and tickle me.","cn":"比我高大的女孩过去总是追赶着胳肢我。"},{"en":"I was tickled to discover that we'd both done the same thing.","cn":"我高兴地发现我俩在做同样的事。"}]},"tins":{"oxford":{"phon":"tɪn","pos":"noun","senses":[{"en":"a chemical element. Tin is a soft silver-white metal that is often mixed with other metals or used to cover them to prevent them from rusting.","cn":"锡"},{"en":"a metal container in which food and drink is sold; the contents of one of these containers","cn":"罐；罐头盒；罐头"}]},"media":{"img":["media/pic/packaging_comp.jpg","media/thumb/tin.jpg"],"uk":"media/uk/tin__gb_1.mp3","us":"media/us/tin__us_1.mp3"}},"time":{"media":{"uk":"media/uk/time__gb_1.mp3","us":"media/us/time__us_1.mp3"},"oxford":{"phon":"taɪm","pos":"noun","senses":[{"en":"what is measured in minutes, hours, days, etc.","cn":"（以分钟、小时、天等计量的）时间","g":"[uncountable]","sc":"minutes/hours/years, etc.","ex":{"en":"The world exists in time and space.","cn":"世界存在于时间与空间之中。"}},{"en":"the time shown on a clock in minutes and hours","cn":"（钟表所显示的）时间，钟点，时刻","g":"[uncountable]","lab":"British English","sc":"minutes/hours/years, etc.","ex":{"en":"What time is it/What’s the time?","cn":"几点了？"}},{"en":"the time measured in a particular part of the world","cn":"（世界某一地区所计量的）时，时间","g":"[uncountable]","sc":"minutes/hours/years, etc.","ex":{"en":"6 o’clock local time","cn":"当地时间 6 点钟"}},{"en":"the time when something happens or when something should happen","cn":"（某事发生或应该发生的）时间，时候","g":"[uncountable, countable]","sc":"minutes/hours/years, etc.","ex":{"en":"What time do you finish work?","cn":"你什么时候下班？"}},{"en":"an amount of time; the amount of time available to work, rest, etc.","cn":"一段时间；（可用于工作、休息等的）一段时间","g":"[uncountable]","sc":"period","ex":{"en":"I can't go with you—I don't have time.","cn":"我不能跟你走——我没时间。"}},{"en":"a period of time, either long or short, during which you do something or something happens","cn":"（或长或短的）一段时间","g":"[singular]","sc":"period","ex":{"en":"His injuries will take a long time to heal.","cn":"他的伤需要很长一段时间才能好。"}},{"en":"a period of history connected with particular events or experiences in people’s lives","cn":"时期；时代；年代；世道","g":"[uncountable, plural]","sc":"period","ex":{"en":"The movie is set at the time of the Russian Revolution.","cn":"这部电影以俄国革命时期为背景。"}},{"en":"an occasion when you do something or when something happens","cn":"次；回","g":"[countable]","lab":"especially North American English","sc":"occasion/event","ex":{"en":"Every time I hear that song I feel happy.","cn":"我每次听到那首歌都感到很愉快。"}},{"en":"an event or occasion that you experience in a particular way","cn":"（以某种方式经历的）事件，时刻","g":"[countable]","sc":"occasion/event","ex":{"en":"Did you have a good time in Spain?","cn":"你在西班牙过得愉快吗？"}},{"en":"how long somebody takes to run a race or complete an event","cn":"（完成赛跑或竞赛项目的）所用时间","g":"[countable, uncountable]","sc":"for race","ex":{"en":"The winner's time was 11.6 seconds.","cn":"获胜者的时间是 11.6 秒。"}},{"en":"the number of beats (= units of rhythm) in a bar of music","cn":"拍子；节拍","g":"[uncountable]","sc":"in music","ex":{"en":"This piece is in four-four time.","cn":"这首乐曲为四四拍。"}},{"en":"the correct speed and rhythm of a piece of music","cn":"（乐曲正确的）速度，节奏","g":"[uncountable]","sc":"in music","ex":{"en":"Try and dance in time to the music (= with the same speed and rhythm).","cn":"要跟上音乐的节奏跳舞。"}},{"en":"to measure how long it takes for something to happen or for somebody to do something","cn":"计时；测定…所需的时间","sc":"measure time","ex":{"en":"‘How long does it take to get to Leeds from here?’ ‘I don’t know, I’ve never timed it.’","cn":"“从这里到利兹需要多长时间？”“我不知道，我从来没有计时过。”"},"pos":"verb"},{"en":"to arrange to do something or arrange for something to happen at a particular time","cn":"为…安排时间；选择…的时机","g":"[often passive]","sc":"arrange time","ex":{"en":"She timed her arrival for shortly after 3.","cn":"她定在 3 点钟刚过到达。"},"pos":"verb"},{"en":"to hit or kick a ball at a particular moment in a sports game","cn":"在某一时刻击球（或踢球）","sc":"in sport","ex":{"en":"She timed the pass perfectly.","cn":"她传球的时机掌握得恰到好处。"},"pos":"verb"},{"en":"a popular US news magazine, published every week. It was started in 1923 by Henry Luce (1898-1967), the husband of Clare Booth Luce, and Briton Hadden (1898-1929). It created offices for its journalists around the world and has developed a particular style of writing which is sometimes called Timese. The magazine now has several different international versions. People consider it a great honour to have their picture on the cover of the magazine, and as a special feature every year it chooses a man or woman of the year.","cn":"时间：每周出版一本受欢迎的美国新闻杂志。它由Clare Booth Luce的丈夫Henry Luce（1898-1967）和Briton Hadden（1898-1929）的丈夫于1923年创立。它为世界各地的新闻工作者设立了办事处，并发展了一种特殊的写作风格，这种风格有时被称为Timese。该杂志现在有几种不同的国际版本。人们认为将照片印在杂志的封面上是一种极大的荣幸，并且每年作为特色节目，它都会选择当年的男人或女人。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"时间","en":"Time is what we measure in minutes, hours, days, and years.","ex":{"en":"...a two-week period of time","cn":"两周的时间"}},{"pos":"N-SING 单数名词","cn":"时刻;时候;钟点","en":"You use time to ask or talk about a specific point in the day, which can be stated in hours and minutes and is shown on clocks.","ex":{"en":"'What time is it?' — 'Eight o'clock.'","cn":"“几点钟了？”——“8点钟。”"}},{"pos":"N-COUNT 可数名词","cn":"规定时间","en":"The time when something happens is the point in the day when it happens or is supposed to happen.","ex":{"en":"Departure times are 08:15 from St Quay, and 18:15 from St Helier.","cn":"从圣奎伊的出发时间是 8 点 15 分，从圣赫利尔的出发时间是 18 点 15 分。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(某一时区的)时间","en":"You use time to refer to the system of expressing time and counting hours that is used in a particular part of the world.","ex":{"en":"The tidal predictions are expressed in Greenwich Mean Time. Add one hour for British Summer Time","cn":"潮汐预报用的是格林尼治标准时间。英国夏令时要在标准时基础上加一小时。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(用来做某事或某事发生的)时间","en":"You use time to refer to the period that you spend doing something or when something has been happening.","ex":{"en":"Adam spent a lot of time in his grandfather's office","cn":"亚当经常呆在他祖父的办公室里。"}},{"pos":"N-SING 单数名词","cn":"(相当长的)一段时间","en":"If you say that something has been happening for a time, you mean that it has been happening for a fairly long period of time.","ex":{"en":"He was also for a time the art critic of 'The Scotsman'","cn":"有相当长的一段时间他为《苏格兰人》报撰写艺术评论。"}},{"pos":"N-COUNT 可数名词","cn":"(某事发生的)一段(或特定)时间","en":"You use time to refer to a period of time or a point in time, when you are describing what is happening then. For example, if something happened at a particular time, that is when it happened. If it happens at all times, it always happens.","ex":{"en":"We were in the same college, which was male-only at that time","cn":"我们那时在同一所学院，当时只招男生。"}},{"pos":"N-COUNT 可数名词","cn":"历史时期;时代","en":"You use time or times to talk about a particular period in history or in your life.","ex":{"en":"They were hard times and his parents had been struggling to raise their family","cn":"那是段艰苦时期，他父母一直艰辛地养家糊口。"}},{"pos":"N-PLURAL 复数名词","cn":"当代;时代潮流","en":"You can use the times to refer to the present time and to modern fashions, tastes, and developments. For example, if you say that someone keeps up with the times, you mean they are fashionable or aware of modern developments. If you say they are behind the times, you mean they are unfashionable or not aware of them.","ex":{"en":"He is unafraid to move with the times","cn":"他敢于与时俱进。"}},{"pos":"N-COUNT 可数名词","cn":"(经历的)一段时间，时期","en":"When you describe the time that you had on a particular occasion or during a particular part of your life, you are describing the sort of experience that you had then.","ex":{"en":"Sarah and I had a great time while the kids were away","cn":"孩子们不在的时候，我和萨拉度过了一段美好时光。"}},{"pos":"N-SING 单数名词","cn":"生命（期）;期限;时限","en":"Your time is the amount of time that you have to live, or to do a particular thing.","ex":{"en":"Now Martin has begun to suffer the effects of AIDS, and he says his time is running out","cn":"现在马丁开始遭受艾滋病的折磨，他说他的生命就要走到尽头。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(从事特定活动的)合适时候","en":"If you say it is time for something, time to do something, or time you did something, you mean that this thing ought to happen or be done now.","ex":{"en":"Opinion polls indicated a feeling among the public that it was time for a change","cn":"民意测验表明，公众认为到了改革的时候了。"}},{"pos":"N-COUNT 可数名词","cn":"次;回","en":"When you talk about a time when something happens, you are referring to a specific occasion when it happens.","ex":{"en":"Every time she travels on the bus it's delayed by at least three hours","cn":"每次她乘公车出行都至少耽搁3个小时。"}},{"pos":"N-COUNT 可数名词","cn":"次","en":"You use time after numbers to say how often something happens.","ex":{"en":"It was her job to make tea three times a day","cn":"她的差事就是每天沏3次茶。"}},{"pos":"N-PLURAL 复数名词","cn":"倍","en":"You use times after numbers when comparing one thing to another and saying, for example, how much bigger, smaller, better, or worse it is.","ex":{"en":"Its profits are rising four times faster than the average company","cn":"它的利润增长速度比一般公司快4倍。"}},{"pos":"CONJ-COORD 连词","cn":"乘以","en":"You use times in arithmetic to link numbers or amounts that are multiplied together to reach a total.","ex":{"en":"Four times six is 24.","cn":"4 乘以 6 等于 24。"}},{"pos":"N-COUNT 可数名词","cn":"(赛跑等)所用时间，成绩","en":"Someone's time in a race is the amount of time it takes them to finish the race.","ex":{"en":"He was over a second faster than his previous best time","cn":"他比自己以前的最好成绩快了 1 秒多。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"拍子;节拍","en":"The time of a piece of music is the number of beats that the piece has in each bar.","ex":{"en":"A reel is in four-four time, and a jig is in six-eight time.","cn":"里尔舞曲是四四拍，吉格舞曲是六八拍。"}},{"pos":"VERB 动词","cn":"给…确定时间;为…安排时间","en":"If you time something for a particular time, you plan or decide to do it or cause it to happen at this time.","ex":{"en":"He timed the election to coincide with new measures to boost the economy","cn":"他把选举安排在振兴经济的新政策出台时。"}},{"pos":"VERB 动词","cn":"测定…所花时间","en":"If you time an action or activity, you measure how long someone takes to do it or how long it lasts.","ex":{"en":"He timed each performance with a stop-watch.","cn":"他用秒表测定每组动作所花的时间。"}},{"pos":"PHRASE 短语","cn":"该是…的时候了;早该…了","en":"If you say it is about time that something was done, you are saying in an emphatic way that it should happen or be done now, and really should have happened or been done sooner.","ex":{"en":"It's about time a few movie makers with original ideas were given a chance","cn":"该给为数不多的几个有创见的电影制作者一个机会了。"}},{"pos":"PHRASE 短语","cn":"提前;预先","en":"If you do something ahead of time, you do it before a particular event or before you need to, in order to be well prepared.","ex":{"en":"Find out ahead of time what regulations apply to your situation.","cn":"提前搞清楚什么规章适用于你的情况。"}},{"pos":"PHRASE 短语","cn":"(思想)先进，领先于时代","en":"If someone is ahead of their time or before their time, they have new ideas a long time before other people start to think in the same way.","ex":{"en":"My mother was ahead of her time. She surrounded me with culture and art.","cn":"我母亲思想前卫，给予了我文化和艺术的熏陶。"}},{"pos":"PHRASE 短语","cn":"一直;始终","en":"If something happens or is done all the time, it happens or is done continually.","ex":{"en":"We can't be together all the time","cn":"我们不能始终在一起。"}},{"pos":"PHRASE 短语","cn":"一次;每次","en":"You say at a time after an amount to say how many things or how much of something is involved in one action, place, or group.","ex":{"en":"Beat in the eggs, one at a time","cn":"打入鸡蛋，一次一个。"}},{"pos":"PHRASE 短语","cn":"随时;任何时候","en":"If something could happen at any time, it is possible that it will happen very soon, though nobody can predict exactly when.","ex":{"en":"Conditions are still very tense and the fighting could escalate at any time.","cn":"局势仍然非常紧张，战斗随时可能升级。"}},{"pos":"PHRASE 短语","cn":"即使在最好的情况下","en":"You say at the best of times when you are making a negative or critical comment to emphasize that it is true even when the circumstances are as favourable as possible.","ex":{"en":"A trade war would be bad at the best of times, but in the current economic climate, it would be a disaster.","cn":"即使在情况最好的时候贸易战都是有害无利的，而在当前这种经济形势下只会是一场灾难。"}},{"pos":"PHRASE 短语","cn":"一度;曾经","en":"If you say that something was the case at one time, you mean that it was the case during a particular period in the past.","ex":{"en":"At one time 400 men, women and children lived in the village.","cn":"曾经有 400 个男人、女人和孩子居住在村子里。"}},{"pos":"PHRASE 短语","cn":"同时","en":"If two or more things exist, happen, or are true at the same time, they exist, happen, or are true together although they seem to contradict each other.","ex":{"en":"I was afraid of her, but at the same time I really liked her","cn":"我害怕她，但同时也确实喜欢她。"}},{"pos":"PHRASE 短语","cn":"然而;不过","en":"At the same time is used to introduce a statement that slightly changes or contradicts the previous statement.","ex":{"en":"I don't think I set out to come up with a different sound for each album. At the same time, I do have a sense of what is right for the moment.","cn":"我不觉得我一开始就特意为每张专辑设定了不同的曲风。然而，我确实知道当时想要的是什么感觉。"}},{"pos":"PHRASE 短语","cn":"有时;间或","en":"You use at times to say that something happens or is true on some occasions or at some moments.","ex":{"en":"The debate was highly emotional at times","cn":"辩论有时变得异常情绪化。"}},{"pos":"PHRASE 短语","cn":"在…出生以前；在…有记忆前","en":"If you say that something was before your time, you mean that it happened or existed before you were born or before you were able to know about it or remember it.","ex":{"en":"'You've never seen the Marilyn Monroe film?' — 'No, I think it was a bit before my time.'","cn":"“你从来没看过玛丽莲·梦露演的电影？”——“是的，她拍电影时我还不记事呢。”"}},{"pos":"PHRASE 短语","cn":"过早","en":"If someone has reached a particular stage in life before their time, they have reached it at a younger age than is normal.","ex":{"en":"The small print has forced me, years before my time, to buy spectacles","cn":"印刷文字过小迫使我早早就要买眼镜戴。"}},{"pos":"PHRASE 短语","cn":"早该发生；早该如此","en":"If you say not before time after a statement has been made about something that has been done, you are saying in an emphatic way that you think it should have been done sooner.","ex":{"en":"The virus is getting more and more attention, and not before time","cn":"这种病毒正受到越来越多的关注，其实早该如此。"}},{"pos":"PHRASE 短语","cn":"结束","en":"If you call time on something, you end it.","ex":{"en":"Scott Hastings has called time on his international career by cutting short his contract.","cn":"斯科特·黑斯廷斯中止合同，结束了他的国际比赛生涯。"}},{"pos":"PHRASE 短语","cn":"坐牢;服刑","en":"Someone who is doing time is in prison.","ex":{"en":"He is serving 11 years for robbery, and did time for a similar offence before that.","cn":"他因犯抢劫罪正在服11年的刑期，此前他也曾因类似罪行蹲过监狱。"}},{"pos":"PHRASE 短语","cn":"永远","en":"If you say that something will be the case for all time, you mean that it will always be the case.","ex":{"en":"The desperate condition of the world is that madness has always been here, and that it will remain so for all time.","cn":"这个世界令人绝望的是，疯狂之事一直存在，而且将永远存在下去。"}},{"pos":"PHRASE 短语","cn":"目前;暂时","en":"If something is the case or will happen for the time being, it is the case or will happen now, but only until something else becomes possible or happens.","ex":{"en":"For the time being, however, immunotherapy is still in its experimental stages","cn":"但免疫疗法目前仍处于实验阶段。"}},{"pos":"PHRASE 短语","cn":"不时地;间或;偶尔","en":"If you do something from time to time, you do it occasionally but not regularly.","ex":{"en":"Her daughters visited him from time to time when he was ill.","cn":"他生病的时候她的女儿们时常去探望他。"}},{"pos":"PHRASE 短语","cn":"常常;几乎总是","en":"If you say that something is the case half the time you mean that it often is the case.","ex":{"en":"Half the time, I don't have the slightest idea what he's talking about.","cn":"我经常一点儿都听不懂他在说什么。"}},{"pos":"PHRASE 短语","cn":"不喜欢/喜欢;不赞成/赞成","en":"If you say that you have no time for a person or thing, you mean you do not like them or approve of them, and if you say that you have a lot of time for a person or thing, you mean you like them or approve of them very much.","ex":{"en":"When I think of what he's done to my mother and me, I've just got no time for him","cn":"想到他对母亲和我所做的一切，我就很讨厌他。"}},{"pos":"PHRASE 短语","cn":"(早)该…了;是时候…了","en":"If you say that it is high time that something happened or was done, you are saying in an emphatic way that it should happen or be done now, and really should have happened or been done sooner.","ex":{"en":"It is high time the Government displayed a more humanitarian approach towards victims of the recession","cn":"政府早该对受到经济衰退影响的人们采取更加人性化的救助措施。"}},{"pos":"PHRASE 短语","cn":"及时;不迟","en":"If you are in time for a particular event, you are not too late for it.","ex":{"en":"I arrived just in time for my flight to London","cn":"我及时赶上了飞往伦敦的航班。"}},{"pos":"PHRASE 短语","cn":"最终;迟早","en":"If you say that something will happen in time or given time, you mean that it will happen eventually, when a lot of time has passed.","ex":{"en":"He would sort out his own problems, in time","cn":"他早晚会解决自己的问题。"}},{"pos":"PHRASE 短语","cn":"合拍/不合拍","en":"If you are playing, singing, or dancing in time with a piece of music, you are following the rhythm and speed of the music correctly. If you are out of time with it, you are not following the rhythm and speed of the music correctly.","ex":{"en":"Her body swayed in time with the music","cn":"她的身体随着音乐节拍摆动。"}},{"pos":"PHRASE 短语","cn":"在…之后","en":"If you say that something will happen, for example, in a week's time or in two years' time, you mean that it will happen a week from now or two years from now.","ex":{"en":"Presidential elections are due to be held in ten days' time","cn":"总统竞选将在10天后如期举行。"}},{"pos":"PHRASE 短语","cn":"提早，提前(到达)","en":"If you arrive somewhere in good time, you arrive early so that there is time to spare before a particular event.","ex":{"en":"If we're out, we always make sure we're home in good time for the programme.","cn":"如果外出，我们总是确保在节目开始之前赶回家。"}},{"pos":"PHRASE 短语","cn":"慢慢来;别急;来得及","en":"If you tell someone that something will happen in good time or all in good time, you are telling them to be patient because it will happen eventually.","ex":{"en":"There will be many advanced exercises that you won't be able to do at first. You will get to them in good time","cn":"有许多难度较大的动作你起初不会做，但慢慢就会了。"}},{"pos":"PHRASE 短语","cn":"立刻;马上","en":"If something happens in no time or in next to no time, it happens almost immediately or very quickly.","ex":{"en":"He's going to be just fine. At his age he'll heal in no time","cn":"他会好起来的。以他的年纪，他很快就会痊愈。"}},{"pos":"PHRASE 短语","cn":"从容地;不慌不忙地","en":"If you do something in your own time, you do it at the speed that you choose, rather than allowing anyone to hurry you.","ex":{"en":"Now, in your own time, tell me what happened.","cn":"现在慢慢告诉我发生了什么事。"}},{"pos":"PHRASE 短语","cn":"在业余时间;在空闲时间","en":"If you do something such as work in your own time in British English, or on your own time in American English, you do it in your free time rather than, for example, at work or school.","ex":{"en":"If I choose to work on other projects in my own time, then I say that is my business.","cn":"如果我选择在业余时间做其他项目，我认为那是我自己的事情。"}},{"pos":"PHRASE 短语","cn":"和着拍子;按节拍","en":"If you keep time when playing or singing music, you follow or play the beat, without going too fast or too slowly.","ex":{"en":"As he sang he kept time on a small drum.","cn":"他边唱边和着节拍敲一个小鼓。"}},{"pos":"PHRASE 短语","cn":"(钟表)走得准","en":"When you talk about how well a watch or clock keeps time, you are talking about how accurately it measures time.","ex":{"en":"Some pulsars keep time better than the earth's most accurate clocks.","cn":"某些脉冲星发送脉冲比地球上最精确的时钟都准时。"}},{"pos":"PHRASE 短语","cn":"腾出时间;留出时间","en":"If you make time for a particular activity or person, you arrange to have some free time so that you can do the activity or spend time with the person.","ex":{"en":"Before leaving the city, be sure to make time for a shopping trip","cn":"离开城市之前，一定要留出时间去买些东西。"}},{"pos":"PHRASE 短语","cn":"(旅途)比预期的快","en":"If you say that you made good time on a journey, you mean it did not take you very long compared to the length of time you expected it to take.","ex":{"en":"They had left early in the morning, on quiet roads, and made good time.","cn":"他们一大早出发，一路上人车稀少，走得比预期快多了。"}},{"pos":"PHRASE 短语","cn":"弥补过去损失的时间","en":"If someone is making up for lost time, they are doing something actively and with enthusiasm because they have not had the opportunity to do it before or when they were younger.","ex":{"en":"Five years older than the majority of officers of his same rank, he was determined to make up for lost time.","cn":"他比同一级别的大多数军官年长 5 岁，因此他决心积极努力来弥补过去损失的时间。"}},{"pos":"PHRASE 短语","cn":"消磨时光;等待时机","en":"If you are marking time, you are doing something that is not particularly useful or interesting while you wait for something more important or interesting to happen.","ex":{"en":"He's really just marking time until he's old enough to leave.","cn":"他其实只是在消磨时光，等年龄一到就退休。"}},{"pos":"PHRASE 短语","cn":"十之八九;几乎总是","en":"If you say that something happens or is the case nine times out of ten or ninety-nine times out of a hundred, you mean that it happens on nearly every occasion or is almost always the case.","ex":{"en":"When they want something, nine times out of ten they get it","cn":"他们想要什么，十之八九都会得到。"}},{"pos":"PHRASE 短语","cn":"有史以来最…的;前所未有的;空前的","en":"If you say that someone or something is, for example, the best writer of all time, or the most successful film of all time, you mean that they are the best or most successful that there has ever been.","ex":{"en":"'Monopoly' is one of the best-selling games of all time","cn":"“大富翁”是有史以来最畅销的游戏之一。"}},{"pos":"PHRASE 短语","cn":"准时;按时","en":"If you are on time, you are not late.","ex":{"en":"Don't worry, she'll be on time","cn":"别急，她会准时到的。"}},{"pos":"PHRASE 短语","cn":"迟早的事;只是时间问题","en":"If you say that it is only a matter of time or only a question of time before something happens, you mean that it cannot be avoided and will definitely happen at some future date.","ex":{"en":"It now seems only a matter of time before they resign","cn":"现在看来，他们辞职是早晚的事。"}},{"pos":"PHRASE 短语","cn":"当今;目前","en":"When you refer to our time or our times you are referring to the present period in the history of the world.","ex":{"en":"It would be wrong to say that the Church doesn't enter the great moral debates of our time.","cn":"要说教会问题不是当代社会道德争论的一大议题，那就错了。"}},{"pos":"PHRASE 短语","cn":"消遣;打发时间","en":"If you do something to pass the time you do it because you have some time available and not because you really want to do it.","ex":{"en":"Without particular interest and just to pass the time, I read a story","cn":"我读了一篇故事，并非有什么特别的兴趣，仅仅为了消遣。"}},{"pos":"PHRASE 短语","cn":"与…寒暄;与…打招呼","en":"If you pass the time of day with someone, you have a short friendly conversation with them.","ex":{"en":"One or two people went up and passed the time of day with her","cn":"一两个人走过去和她打了招呼。"}},{"pos":"PHRASE 短语","cn":"(为争取时间)故意拖延","en":"If you play for time, you try to make something happen more slowly, because you do not want it to happen or because you need time to think about what to do if it happens.","ex":{"en":"The president's decision is being seen as an attempt to play for time.","cn":"总统的决定被视为试图争取时间而故意拖延。"}},{"pos":"PHRASE 短语","cn":"需要时间;耗时","en":"If you say that something will take time, you mean that it will take a long time.","ex":{"en":"Change will come, but it will take time","cn":"会有变化的，但这需要时间。"}},{"pos":"PHRASE 短语","cn":"不着急;不慌忙;慢慢来","en":"If you take your time doing something, you do it quite slowly and do not hurry.","ex":{"en":"'Take your time,' Cross told him. 'I'm in no hurry.'","cn":"“慢慢来，”克罗斯对他说，“我一点都不急。”"}},{"pos":"PHRASE 短语","cn":"认时间;认钟表","en":"If a child can tell the time, they are able to find out what the time is by looking at a clock or watch.","ex":{"en":"My four-year-old daughter cannot quite tell the time.","cn":"我4岁大的女儿还不大会看表。"}},{"pos":"PHRASE 短语","cn":"反复地;屡次;一再","en":"If something happens time after time, it happens in a similar way on many occasions.","ex":{"en":"Burns had escaped from jail time after time","cn":"伯恩斯屡次越狱。"}},{"pos":"PHRASE 短语","cn":"时光飞逝","en":"If you say that time flies, you mean that it seems to pass very quickly.","ex":{"en":"Time flies when you're having fun.","cn":"开心的时光总是飞逝而去。"}},{"pos":"PHRASE 短语","cn":"过得愉快;玩得高兴","en":"If you have the time of your life, you enjoy yourself very much indeed.","ex":{"en":"We're taking our little grandchild away with us. We'll make sure he has the time of his life","cn":"我们会把小孙子带走。我们一定会让他过得开心。"}},{"pos":"PHRASE 短语","cn":"须赶快;须尽快","en":"If you say there is no time to lose or no time to be lost, you mean you must hurry as fast as you can to do something.","ex":{"en":"He rushed home, realising there was no time to lose.","cn":"他意识到时间紧迫，于是急速赶回家。"}},{"pos":"PHRASE 短语","cn":"时间会验证","en":"If you say that time will tell whether something is true or correct, you mean that it will not be known until some time in the future whether it is true or correct.","ex":{"en":"Only time will tell whether Broughton's optimism is justified","cn":"只有时间会验证布劳顿的乐观是否合理。"}},{"pos":"PHRASE 短语","cn":"立即;马上","en":"If you waste no time in doing something, you take the opportunity to do it immediately or quickly.","ex":{"en":"Tom wasted no time in telling me why he had come.","cn":"汤姆马上告诉了我他来的原因。"}},{"pos":"","cn":"","en":"time and again→see: ; to the end of time→see: ; in the fullness of time→see: ; there's no time like the present→see: ; the time is ripe→see: ;"}]},"examples":[{"en":"‘Were you taught by Professor Pascal?’ ‘No, he was before my time.’ “","cn":"帕斯卡尔教授教过你吗？” “没有，他教书时我还没有入校呢。”"},{"en":"Since the success of her novel, people shake her hand who once wouldn't have given her the time of day.","cn":"自从她的小说获得成功之后，曾经懒得答理她的人也跟她握起手来。"}]},"tip":{"media":{"uk":"media/uk/tip__gb_1.mp3","us":"media/us/tip__us_1.mp3"},"oxford":{"phon":"tɪp","pos":"noun","senses":[{"en":"a small piece of advice about something practical","cn":"指点；实用的提示","lab":"British English, informal，，","sc":"advice","ex":{"en":"handy tips for buying a computer","cn":"购买电脑几点有用的提示"}},{"en":"a secret or expert piece of advice about what the result of a competition, etc. is likely to be, especially about which horse is likely to win a race","cn":"（尤指有关赛马的）内幕消息，指点","lab":"informal","sc":"advice","ex":{"en":"a hot tip for the big race","cn":"赛马大赛的最新内幕消息"}},{"en":"secret information that somebody gives, for example to the police, to warn them about an illegal activity that is going to happen or has happened","cn":"举报；密报；线报","lab":"North American English","sc":"advice","ex":{"en":"The man was arrested after an anonymous tip.","cn":"有人匿名举报后，那个人被抓了起来。"}},{"en":"a small amount of extra money that you give to somebody, for example somebody who serves you in a restaurant","cn":"小费；小账","sc":"extra money","ex":{"en":"to leave a tip","cn":"留小费"}},{"en":"the thin, pointed end of something","cn":"尖端；尖儿；端","sc":"end of something","ex":{"en":"the tips of your fingers","cn":"手指尖"}},{"en":"a small part that fits on or over the end of something","cn":"（装在顶端的）小部件","sc":"end of something","ex":{"en":"a walking stick with a rubber tip","cn":"带橡皮头的手杖"}},{"en":"a place where you can take rubbish and leave it","cn":"垃圾场；垃圾堆","lab":"British English","sc":"for rubbish"},{"en":"an untidy place","cn":"脏乱的地方","lab":"British English, informal, disapproving，，，，","sc":"untidy place","ex":{"en":"Their flat is a tip!","cn":"他们的寓所简直是个猪窝！"}},{"en":"to give somebody an extra amount of money to thank them for something they have done for you as part of their job","cn":"给小费；付小账","g":"[intransitive, transitive]","sc":"give extra money","ex":{"en":"Americans were always welcome because they tended to tip heavily.","cn":"美国人总是受欢迎，因为他们往往给很多小费。"},"pos":"verb"},{"en":"to move so that one end or side is higher than the other; to move something into this position","cn":"（使）倾斜，倾倒，翻覆","g":"[intransitive, transitive]","sc":"lean/pour/push at an angle","ex":{"en":"The boat tipped to one side.","cn":"船向一边倾斜。"},"pos":"verb"},{"en":"to make something/somebody come out of a container or its/their position by holding or lifting it/them at an angle","cn":"倒出；倾倒；倾覆","g":"[transitive]","sc":"lean/pour/push at an angle","ex":{"en":"She tipped the dirty water down the drain.","cn":"她把脏水倒入了下水道。"},"pos":"verb"},{"en":"to touch something lightly so that it moves in a particular direction","cn":"轻触；轻碰","g":"[transitive]","sc":"lean/pour/push at an angle","ex":{"en":"The goalkeeper just managed to tip the ball over the crossbar.","cn":"守门员刚好把球捅出球门的横梁。"},"pos":"verb"},{"en":"to leave rubbish somewhere outdoors in order to get rid of it","cn":"（在户外）倒垃圾","g":"[intransitive, transitive]","lab":"British English","sc":"leave rubbish","ex":{"en":"‘No tipping.’ (= for example, on a notice)","cn":"“此处禁止倒垃圾。”"},"pos":"verb"},{"en":"to say in advance that somebody/something will be successful","cn":"预言…获胜；事先说…会成功","g":"[transitive, usually passive]","lab":"especially British English","sc":"predict success","ex":{"en":"The band is being tipped for the top.","cn":"人们说这支乐队将位居榜首。"},"pos":"verb"},{"en":"to cover the end or edge of something with a colour, a substance, etc.","cn":"（用颜色、物质等）覆盖…的末端，遮盖…的边","g":"[transitive, usually passive]","sc":"cover end","ex":{"en":"The wings are tipped with yellow.","cn":"翅膀的尖端呈黄色。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"末梢;尖端;顶端","en":"The tip of something long and narrow is the end of it.","ex":{"en":"The sleeves covered his hands to the tips of his fingers","cn":"袖子遮住了他的手，一直盖到指尖。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)倾斜;(使)斜侧","en":"If you tip an object or part of your body or if it tips, it moves into a sloping position with one end or side higher than the other.","ex":{"en":"He leaned away from her, and she had to tip her head back to see him","cn":"他倾着身子避开她，她不得不把头向后歪着看他。"}},{"pos":"VERB 动词","cn":"倾倒;倒出","en":"If you tip something somewhere, you pour it there.","ex":{"en":"Tip the vegetables into a bowl","cn":"把蔬菜倒进碗里。"}},{"pos":"VERB 动词","cn":"扔掉,倒掉(垃圾)","en":"To tip rubbish means to get rid of it by leaving it somewhere.","ex":{"en":"...the costs of tipping rubbish in landfills","cn":"在废弃物填埋场倾倒垃圾的成本"}},{"pos":"N-COUNT 可数名词","cn":"垃圾场","en":"A tip is a place where rubbish is left.","ex":{"en":"Officers had found a large bread knife on the rubbish tip…","cn":"警察在垃圾场发现了一把很大的面包刀。"}},{"pos":"N-COUNT 可数名词","cn":"脏乱的场所","en":"If you describe a place as a tip, you mean it is very untidy.","ex":{"en":"The flat is an absolute tip.","cn":"这套公寓简直就是个垃圾场。"}},{"pos":"VERB 动词","cn":"给…小费","en":"If you tip someone such as a waiter in a restaurant, you give them some money in order to thank them for their services.","ex":{"en":"Do you really think it's customary to tip the waiters?","cn":"你真的认为给侍者小费是约定俗成的吗？"}},{"pos":"N-COUNT 可数名词","cn":"小费","en":"If you give a tip to someone such as a waiter in a restaurant, you give them some money to thank them for their services.","ex":{"en":"I gave the barber a tip","cn":"我给了理发师小费。"}},{"pos":"N-COUNT 可数名词","cn":"诀窍;忠告;指导","en":"A tip is a useful piece of advice.","ex":{"en":"It shows how to prepare a CV, and gives tips on applying for jobs.","cn":"它说明了如何准备简历，并就如何申请职位提了些建议。"}},{"pos":"VERB 动词","cn":"认定…会(做某事或获得成功)","en":"If a person is tipped to do something or is tipped for success at something, experts or journalists believe that they will do that thing or achieve that success.","ex":{"en":"He is tipped to be the country's next foreign minister","cn":"他被认定会成为该国下一任外交部长。"}},{"pos":"N-COUNT 可数名词","cn":"(对赛马、比赛结果的)预测，内幕消息","en":"Someone's tip for a race or competition is their advice on its likely result, especially to someone who wants to bet money on the result.","ex":{"en":"I've a tip for the races…","cn":"我有一条关于赛马比赛的内部消息。"}},{"pos":"PHRASE 短语","cn":"(事物的)端倪，表面一小部分，冰山一角","en":"If you say that a problem is the tip of the iceberg, you mean that it is one small part of a much larger problem.","ex":{"en":"Unless we're all a lot more careful, the people who have died so far will be just the tip of the iceberg.","cn":"除非我们都加倍小心，否则死者的人数会比现在多得多。"}},{"pos":"PHRASE 短语","cn":"使占优势","en":"If something tips the scales or tips the balance, it gives someone a slight advantage.","ex":{"en":"Today's slightly shorter race could well help to tip the scales in his favour","cn":"今天距离稍短的赛跑可能会对他占据优势大有助益。"}},{"pos":"PHRASE 短语","cn":"话到嘴边(却没说出来)","en":"If a comment or question is on the tip of your tongue, you really want to say it or ask it, but you decide not to say it.","ex":{"en":"It was on the tip of Mahoney's tongue to say the boss was out","cn":"马奥尼想说老板出去了，话到嘴边却没说出口。"}},{"pos":"","cn":"","en":"相关词组：tip off tip over tip up"}]},"examples":[{"en":"The bus stopped abruptly, nearly tipping me out of my seat.","cn":"公共汽车突然刹车，差点儿把我从座位上甩出去。"},{"en":"The actor is tipped to win an Oscar for his performance.","cn":"这位演员因表演出色而被认为有望获得奥斯卡奖。"}]},"time-consuming":{"oxford":{"phon":"ˈtaɪm kənsjuːmɪŋ","pos":"adjective","senses":[{"en":"taking or needing a lot of time","cn":"费时的；耗时间的","ex":{"en":"a difficult and time-consuming process","cn":"困难而又费时的过程"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"耗时的;费时的","en":"If something is time-consuming, it takes a lot of time.","ex":{"en":"It's just very time consuming to get such a large quantity of data","cn":"获取如此大量的数据非常费时。"}}]},"media":{"uk":"media/uk/time_consuming_1_gb_1.mp3","us":"media/us/time_consuming_1_us_1.mp3"},"examples":[{"en":"a difficult and time-consuming process","cn":"困难而又费时的过程"},{"en":"a complex and time-consuming process","cn":"复杂而费时的过程"}]},"tidy":{"media":{"uk":"media/uk/tidy__gb_1.mp3","us":"media/us/tidy__us_1.mp3"},"oxford":{"phon":"ˈtaɪdi","pos":"adjective","senses":[{"en":"arranged neatly and with everything in order","cn":"整洁的；整齐的；井然有序的；井井有条的","lab":"especially British English","ex":{"en":"a tidy desk","cn":"整洁的书桌"}},{"en":"keeping things neat and in order","cn":"爱整洁的；爱整齐的","lab":"especially British English","ex":{"en":"I'm a tidy person.","cn":"我这个人讲究整洁。"}},{"en":"a tidy amount of money is fairly large","cn":"高额的；可观的","g":"[only before noun]","lab":"informal","ex":{"en":"It must have cost a tidy sum.","cn":"这准花了相当大的一笔钱。"}},{"en":"to make something look neat by putting things in the place where they belong","cn":"使整洁；使整齐；使有条理；整理","ex":{"en":"I spent all morning cleaning and tidying.","cn":"我用了整个上午的时间清扫整理。"},"pos":"verb"},{"en":"a container for putting small objects in, in order to keep a place tidy","cn":"盛零碎物品的容器","ex":{"en":"a desk tidy","cn":"案头文具盒"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"整洁的;整齐的","en":"Something that is tidy is neat and is arranged in an organized way.","ex":{"en":"Having a tidy desk can seem impossible if you have a busy, demanding job","cn":"如果工作忙、难度大，要想保持桌面整洁似乎不太可能。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"整洁的;有条理的","en":"Someone who is tidy likes everything to be neat and arranged in an organized way.","ex":{"en":"She's obsessively tidy, always hoovering and polishing.","cn":"她有洁癖，整天不是用吸尘器吸尘，就是擦来擦去。"}},{"pos":"VERB 动词","cn":"收拾，整理(房间、橱柜等)","en":"When you tidy a place such as a room or cupboard, you make it neat by putting things in their proper places.","ex":{"en":"She made her bed, and tidied her room.","cn":"她整理了床铺，收拾了自己的房间。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一大笔(钱)","en":"A tidy amount of money is a large amount.","ex":{"en":"The opportunities are there to make a tidy profit.","cn":"赚大钱的机会就在那儿摆着。"}},{"pos":"","cn":"","en":"相关词组：tidy away tidy up"}]},"examples":[{"en":"She keeps her flat very tidy.","cn":"她把她的单元房间保持得很整洁。"},{"en":"I spent all morning cleaning and tidying.","cn":"我用了整个上午的时间清扫整理。"}]},"timetable":{"media":{"uk":"media/uk/timetable__gb_1.mp3","us":"media/us/timetable__us_1.mp3"},"oxford":{"phon":"ˈtaɪmteɪbl","pos":"noun","senses":[{"en":"a chart showing the times at which trains, buses and planes leave and arrive","cn":"时间表；时刻表","lab":"especially British English","ex":{"en":"a bus/train timetable","cn":"公共汽车／火车时刻表"}},{"en":"a chart or plan of the classes that a student or teacher has in school each week","cn":"课程表","lab":"British English","ex":{"en":"We have a new timetable each term.","cn":"我们每学期都有新课程表。"}},{"en":"a plan of when you expect or hope particular events to happen","cn":"预定计划；时间安排","ex":{"en":"I have a busy timetable this week (= I have planned to do many things).","cn":"这个星期我的时间安排得很紧。"}},{"en":"to arrange for something to take place at a particular time","cn":"为…安排时间","ex":{"en":"A series of discussion groups have been timetabled for the afternoons.","cn":"一系列小组讨论已安排在几个下午进行。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"时间表;时间安排;日程表","en":"A timetable is a plan of the times when particular events are to take place.","ex":{"en":"The timetable was hopelessly optimistic…","cn":"时间表制定得过于乐观。"}},{"pos":"N-COUNT 可数名词","cn":"课程表;课程","en":"In a school or college, a timetable is a list that shows the times in the week at which particular subjects are taught. You can also refer to the range of subjects that a student learns or the classes that a teacher teaches as their timetable .","ex":{"en":"Options are offered subject to staff availability and the constraints of the timetable","cn":"课程选择视教师的时间与课程表的限制而定。"}},{"pos":"N-COUNT 可数名词","cn":"交通时刻表","en":"A timetable is a list of the times when trains, boats, buses, or aeroplanes are supposed to arrive at or leave from a particular place.","ex":{"en":"For a local bus timetable, contact Dyfed County Council.","cn":"若要当地公共汽车时刻表，请与达费德郡政务委员会联系。"}},{"pos":"VERB 动词","cn":"为…安排时间","en":"If something is timetabled, it is scheduled to happen or do something at a particular time.","ex":{"en":"On both days, three very different trains will be timetabled","cn":"这两天都将安排发出 3 列时刻不同的火车。"}}]},"examples":[{"en":"Sport is no longer so important in the school timetable (= all the subjects that are taught at schools).","cn":"体育课在学校的课程表上已不再是重点课。"},{"en":"A series of discussion groups have been timetabled for the afternoons.","cn":"一系列小组讨论已安排在几个下午进行。"}]},"title":{"media":{"uk":"media/uk/title__gb_1.mp3","us":"media/us/title__us_1.mp3"},"oxford":{"phon":"ˈtaɪtl","pos":"noun","senses":[{"en":"the name of a book, poem, painting, piece of music, etc.","cn":"（书、诗歌、图画、乐曲等的）名称，标题，题目","g":"[countable]","ex":{"en":"What's title of her new book?","cn":"她新书的书名是什么？"}},{"en":"a particular book or magazine","cn":"（书刊的）一种，一本","g":"[countable]","ex":{"en":"The company publishes twenty new titles a year.","cn":"这家公司一年出版二十种新书。"}},{"en":"a word in front of a person’s name to show their rank or profession, whether or not they are married, etc.","cn":"（人名前表示地位、职业、婚否等的）称号，头衔，职称，称谓","g":"[countable]","lab":"British English","ex":{"en":"The present duke inherited the title from his father.","cn":"现在的公爵承袭的是他父亲的爵位。"}},{"en":"a name that describes a job","cn":"职位名称；职称","g":"[countable]","ex":{"en":"The official title of the job is ‘Administrative Assistant’.","cn":"这个职位的正式名称为“行政助理”。"}},{"en":"the position of being the winner of a competition, especially a sports competition","cn":"（竞赛、体育比赛的）冠军","g":"[countable]","ex":{"en":"She has won three world titles.","cn":"她已获得三项世界冠军。"}},{"en":"the legal right to own something, especially land or property; the document that shows you have this right","cn":"（尤指土地或财产的）所有权，所有权凭证，房地契","g":"[uncountable, countable]","lab":"law","ex":{"en":"He claims he has title to the land.","cn":"他声称拥有这块土地的所有权。"}},{"en":"to give a book, piece of music, etc. a particular name","cn":"（给书、乐曲等）加标题，定题目","ex":{"en":"Their first album was titled ‘Made in Valmez’.","cn":"他们的第一张专辑定名为 Made in Valmez。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"题目;标题;名称","en":"The title of a book, play, film, or piece of music is its name.","ex":{"en":"'Patience and Sarah' was first published in 1969 under the title 'A Place for Us'.","cn":"《佩兴丝与萨拉》一书最初于1969年出版时以《属于我们的地方》为名。"}},{"pos":"VERB 动词","cn":"为…加上题目(或标题)","en":"When a writer, composer, or artist titles a work, they give it a title.","ex":{"en":"Pirandello titled his play 'Six Characters in Search of an Author'","cn":"皮兰德娄把他的戏剧命名为《六个寻找作者的剧中人》。"}},{"pos":"N-COUNT 可数名词","cn":"(书刊等的)一种，一本","en":"Publishers and booksellers often refer to books or magazines as titles .","ex":{"en":"It has become the biggest publisher of new poetry in Britain, with 50 new titles a year.","cn":"它成为英国最大的新诗出版商，每年推出新书 50 种。"}},{"pos":"N-COUNT 可数名词","cn":"头衔;称谓","en":"A person's title is a word such as 'Sir', 'Lord', or 'Lady' that is used in front of their name, or a phrase that is used instead of their name, and indicates that they have a high rank in society.","ex":{"en":"Her husband was also honoured with his title 'Sir Denis'","cn":"她丈夫也被封为“丹尼斯爵士”。"}},{"pos":"N-COUNT 可数名词","cn":"称呼;职称","en":"Someone's title is a word such as 'Mr', 'Mrs', or 'Doctor', that is used before their own name in order to show their status or profession.","ex":{"en":"She has been awarded the title Professor.","cn":"她已被授予教授职称。"}},{"pos":"N-COUNT 可数名词","cn":"职务名称","en":"Someone's title is a name that describes their job or status in an organization.","ex":{"en":"He was given the title of deputy prime minister…","cn":"他被授予副总理之职。"}},{"pos":"N-COUNT 可数名词","cn":"冠军","en":"If a person or team wins a particular title, they win a sports competition that is held regularly. Usually a person keeps a title until someone else defeats them.","ex":{"en":"He became Jamaica's first Olympic gold medallist when he won the 400m title in 1948","cn":"他 1948 年赢得 400 米冠军，成为牙买加第一位奥运会金牌得主。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指土地或财产的)所有权","en":"Title is the legal ownership of something, especially land or property.","ex":{"en":"He never had title to the property.","cn":"他从来就不具有这项财产的所有权。"}}]},"examples":[{"en":"Their first album was titled ‘Made in Valmez’.","cn":"他们的第一张专辑定名为 Made in Valmez。"},{"en":"His poems were published under the title of ‘Love and Reason’.","cn":"他的诗是以《爱情与理智》为题发表的。"}]},"tiny":{"media":{"uk":"media/uk/tiny__gb_1.mp3","us":"media/us/tiny__us_1.mp3","img":["media/ldoce/img/huge.jpg"]},"oxford":{"phon":"ˈtaɪni","pos":"adjective","senses":[{"en":"very small in size or amount","cn":"极小的；微小的；微量的","ex":{"en":"a tiny baby","cn":"纤弱的婴儿"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极小的;非常小的","en":"Something or someone that is tiny is extremely small.","ex":{"en":"The living room is tiny","cn":"起居室非常小。"}}]},"examples":[{"en":"Only a tiny minority hold such extreme views.","cn":"只有极少数人持这样极端的观点。"},{"en":"a tiny baby","cn":"纤弱的婴儿"}]},"timely":{"media":{"uk":"media/uk/timely__gb_1.mp3","us":"media/us/timely__us_1.mp3"},"oxford":{"phon":"ˈtaɪmli","pos":"adjective","senses":[{"en":"happening at exactly the right time","cn":"及时的；适时的","ex":{"en":"A nasty incident was prevented by the timely arrival of the police.","cn":"警察的及时到来阻止了一次严重事件。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"及时的;适时的","en":"A timely event happens at a moment when it is useful, effective, or relevant.","ex":{"en":"The recent outbreaks of cholera are a timely reminder that this disease is still a serious health hazard","cn":"最近霍乱的爆发及时提醒了人们该疾病仍然会严重危害健康。"}}]},"examples":[{"en":"A nasty incident was prevented by the timely arrival of the police.","cn":"警察的及时到来阻止了一次严重事故。"},{"en":"This has been a timely reminder to us all.","cn":"对我们大家来说这个提醒非常及时。"}]},"titles":{"oxford":{"phon":"ˈtaɪtl","pos":"noun","senses":[{"en":"the name of a book, poem, painting, piece of music, etc. （","cn":"书、诗歌、图画、乐曲等的）名称，标题，题目"},{"en":"a particular book or magazine （","cn":"书刊的）一种，一本"}]},"media":{"uk":"media/uk/title__gb_1.mp3","us":"media/us/title__us_1.mp3"}},"ticking":{"media":{"uk":"media/uk/ticking__gb_1.mp3","us":"media/us/ticking__us_1.mp3"},"oxford":{"phon":"ˈtɪkɪŋ","pos":"noun","senses":[{"en":"a type of strong cotton cloth that is often marked with a pattern of lines, used especially for making mattress and pillow covers","cn":"（尤指做床垫和枕套用的）结实条纹棉布"}]}},"tightly":{"media":{"uk":"media/uk/tightly__gb_1.mp3","us":"media/us/tightly__us_1.mp3"},"oxford":{"phon":"ˈtaɪtli","pos":"adverb","senses":[{"en":"in a way that is very strict and hard to resist, avoid, etc.","cn":"严密地；严格地；严厉地","ex":{"en":"The project's finances are tightly controlled.","cn":"项目的财务状况受到严格控制。"}},{"en":"securely in position; in a way that is difficult to move, open or separate","cn":"紧紧地；牢固地","ex":{"en":"Her eyes were tightly closed.","cn":"她的双眼紧闭着。"}},{"en":"close together; leaving little or no space between","cn":"紧密地","ex":{"en":"a tightly packed crowd of tourists","cn":"挤得严严实实的旅游人群"}}]},"examples":[{"en":"a tightly packed crowd of tourists","cn":"挤得严严实实的旅游人群"},{"en":"He held on tightly to her arm.","cn":"他紧紧抓住她的手臂。"}]},"timber":{"media":{"uk":"media/uk/timber__gb_1.mp3","us":"media/us/timber__us_1.mp3"},"oxford":{"phon":"ˈtɪmbə(r)","pos":"noun","senses":[{"en":"trees that are grown to be used in building or for making things","cn":"（用于建筑或制作物品的）树木，林木；用材林","g":"[uncountable]","ex":{"en":"the timber industry","cn":"林木业"}},{"en":"wood that is prepared for use in building, etc.","cn":"（建筑等用的）木材，木料","g":"[uncountable]","lab":"especially British English","ex":{"en":"houses built of timber","cn":"木屋"}},{"en":"a long heavy piece of wood used in building a house or ship","cn":"（建造房屋用的）大木料，栋木；（造船用的）肋材","g":"[countable, usually plural]","ex":{"en":"roof timbers","cn":"房檩"}},{"en":"used to warn people that a tree that has been cut is about to fall","cn":"（砍伐树木时喊）放树啦！"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"木材;原木;树木；林木","en":"Timber is wood that is used for building houses and making furniture. You can also refer to trees that are grown for this purpose as timber .","ex":{"en":"These Severn Valley woods have been exploited for timber since Saxon times.","cn":"从撒克逊时代起就开始采伐塞文山谷的这些树林获取木料。"}},{"pos":"N-COUNT 可数名词","cn":"(造船或建屋用的)栋木，大梁","en":"The timbers of a ship or house are the large pieces of wood that have been used to build it.","ex":{"en":"...a bird nestling in the timbers of the roof.","cn":"栖息于屋顶横梁上的鸟"}}]},"examples":[{"en":"the timber industry","cn":"林木业"},{"en":"houses built of timber","cn":"木屋"}]},"tire":{"media":{"uk":"media/uk/tire__gb_1.mp3","us":"media/us/tire__us_1.mp3","img":["media/ldoce/img/mountain_bike.jpg"]},"oxford":{"phon":"ˈtaɪə(r)","pos":"verb","senses":[{"en":"to become tired and feel as if you want to sleep or rest; to make somebody feel this way","cn":"（使）疲劳，疲倦，困倦","ex":{"en":"Her legs were beginning to tire.","cn":"她的双腿开始感到累了。"}},{"en":"a thick rubber ring that fits around the edge of a wheel of a car, bicycle, etc.","cn":"轮胎","ex":{"en":"a front/rear tire","cn":"前胎；后胎"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)感到疲劳;(使)感到累","en":"If something tires you or if you tire, you feel that you have used a lot of energy and you want to rest or sleep.","ex":{"en":"If driving tires you, take the train","cn":"如果开车觉得累，就乘火车吧。"}},{"pos":"VERB 动词","cn":"厌烦;厌倦","en":"If you tire of something, you no longer wish to do it, because you have become bored of it or unhappy with it.","ex":{"en":"He felt he would never tire of international cricket","cn":"他认为自己永远不会对国际板球赛生厌。"}},{"pos":"N-COUNT 可数名词","cn":"同 tyre","en":"A tire is the same as a tyre ."},{"pos":"","cn":"","en":"相关词组：tire out"}]},"examples":[{"en":"He went to Harvard — as he never tires of reminding us.","cn":"他上过哈佛，他总是不厌其烦地一再提醒我们这一点。"},{"en":"He has made a good recovery but still tires easily.","cn":"他已康复得不错，但仍然容易感到疲劳。"}]},"times":{"media":{"uk":"media/uk/times__gb_1.mp3","us":"media/us/times__us_1.mp3"},"oxford":{"phon":"taɪmz","pos":"preposition","senses":[{"en":"multiplied by","cn":"乘以","ex":{"en":"Five times two is/equals ten (= 5 × 2 = 10).","cn":"五乘以二等于十。"}},{"en":"used in comparisons to show how much more, better, etc. something is than something else","cn":"（用于比较）倍","ex":{"en":"three times as long as something","cn":"某物的三倍长"},"pos":"noun"},{"en":"to multiply a number","cn":"（用某数）乘","lab":"figurative","ex":{"en":"You times the six by four to get twenty-four.","cn":"六乘以四得二十四。"},"pos":"verb"}]},"examples":[{"en":"Five times two is/equals ten (5 × 2 = 10).","cn":"五乘以二等于十。"},{"en":"three times the length of sth","cn":"三倍于某物的长度"}]},"tin":{"media":{"img":["media/pic/packaging_comp.jpg","media/thumb/tin.jpg"],"uk":"media/uk/tin__gb_1.mp3","us":"media/us/tin__us_1.mp3"},"oxford":{"phon":"tɪn","pos":"noun","senses":[{"en":"a metal container in which food is sold; the contents of one of these containers","cn":"罐；罐头盒；罐头","g":"[countable]","lab":"British English","ex":{"en":"Open the tin and drain the tuna.","cn":"打开罐头把金枪鱼沥干。"}},{"en":"a metal container with a lid (= cover), in the shape of a cylinder, in which paint, glue, etc. is sold and stored; the contents of one of these containers","cn":"（盛涂料、胶水等的）马口铁罐，白铁桶；罐装物","g":"[countable]","lab":"British English","ex":{"en":"a tin of varnish","cn":"一罐清漆"}},{"en":"a metal container with a lid (= cover) used for keeping food in","cn":"金属食品盒","g":"[countable]","ex":{"en":"a biscuit/cake/cookie tin","cn":"饼干／蛋糕／曲奇饼盒"}},{"en":"a metal container used for cooking food in","cn":"烘焙用的金属器皿；烤盘；烤模","g":"[countable]","lab":"British English","ex":{"en":"a cake/loaf tin","cn":"蛋糕/面包罐"}},{"en":"a chemical element. Tin is a soft silver-white metal that is often mixed with other metals or used to cover them to prevent them from rusting.","cn":"锡","g":"[uncountable]","ex":{"en":"a tin mine","cn":"锡矿"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"锡","en":"Tin is a soft silvery-white metal.","ex":{"en":"...a factory that turns scrap metal into tin cans.","cn":"把废弃金属制成锡罐的工厂"}},{"pos":"N-COUNT 可数名词","cn":"罐头","en":"A tin is a metal container which is filled with food and sealed in order to preserve the food for long periods of time.","ex":{"en":"She popped out to buy a tin of soup.","cn":"她飞快地跑去买了一听罐头汤。"}},{"pos":"N-COUNT 可数名词","cn":"金属罐;马口铁罐","en":"A tin is a metal container with a lid in which things such as biscuits, cakes, or tobacco can be kept.","ex":{"en":"Store the cookies in an airtight tin","cn":"把饼干存放在密封的金属罐中。"}},{"pos":"N-COUNT 可数名词","cn":"(蛋糕或面包)烤模，烤盘","en":"A baking tin is a metal container used for baking things such as cakes and bread in an oven.","ex":{"en":"Pour the mixture into the cake tin and bake for 45 minutes.","cn":"把混合物倒进烤模烤制 45 分钟。"}}]},"examples":[{"en":"I paid £150 for this camera and am more than happy with it. It does exactly what it says on the tin!","cn":"我花 150 英镑买了这架照相机，真是十分令人满意。它和广告所说的别无二致！"},{"en":"Next, add two tins of tomatoes.","cn":"然后，加两罐番茄。"}]},"tied":{"oxford":{"phon":"taɪd","pos":"adjective","senses":[{"en":"rented to somebody on the condition that they work for the owner","cn":"只租给雇工居住的","ex":{"en":"a tied cottage on a farm","cn":"农场里租给雇工的农舍"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(农舍、房屋)出租的，供雇工租住的","en":"A tied cottage or house belongs to a farmer or other employer and is rented to someone who works for him or her.","ex":{"en":"He lives with his wife in a tied cottage in Hamsey.","cn":"他和妻子住在哈姆西的雇工农舍里。"}}]},"media":{"uk":"media/uk/tied__gb_1.mp3","us":"media/us/tied__us_1.mp3"},"examples":[{"en":"a tied cottage on a farm","cn":"农场里租给雇工的农舍"}]},"ti":{"oxford":{"phon":"tiː","pos":"noun","senses":[{"en":"the 7th note of a major scale","cn":"大调音阶的第 7 音"}]},"media":{"uk":"media/uk/ti__gb_1.mp3","us":"media/us/ti__us_1.mp3"}},"tiring":{"media":{"uk":"media/uk/tiring__gb_1.mp3","us":"media/us/tiring__us_1.mp3"},"oxford":{"phon":"ˈtaɪərɪŋ","pos":"adjective","senses":[{"en":"making you feel the need to sleep or rest","cn":"令人困倦的；使人疲劳的；累人的","ex":{"en":"It had been a long, tiring day.","cn":"这一天让人感到又累又长。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引起疲劳的;累人的","en":"If you describe something as tiring, you mean that it makes you tired so that you want to rest or sleep.","ex":{"en":"It had been a long and tiring day","cn":"这是漫长而又累人的一天。"}}]},"examples":[{"en":"It had been a long tiring day.","cn":"这一天让人感到又累又长。"},{"en":"We’ve all had a long tiring day.","cn":"我们大家都经历了漫长而劳累的一天。"}]},"tissue":{"oxford":{"phon":"ˈtɪʃuː","pos":"noun","senses":[{"en":"a piece of soft paper, used especially as a handkerchief","cn":"（尤指用作手帕的）纸巾，手巾纸","g":"[countable]","ex":{"en":"a box of tissues","cn":"一盒纸巾"}},{"en":"a collection of cells that form the different parts of humans, animals and plants","cn":"（人、动植物细胞的）组织","g":"[uncountable]","ex":{"en":"muscle/brain/lung tissue","cn":"肌肉／大脑／肺组织"}},{"en":"very thin paper used for wrapping and packing things that break easily","cn":"（用于包装易碎物品的）薄纸，绵纸","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(动植物的)组织","en":"In animals and plants, tissue consists of cells that are similar to each other in appearance and that have the same function.","ex":{"en":"As we age we lose muscle tissue","cn":"肌肉组织会随着我们日趋衰老而萎缩。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(用于包装易损物品的)薄纸，绵纸","en":"Tissue or tissue paper is thin paper that is used for wrapping things that are easily damaged, such as objects made of glass or china."},{"pos":"N-COUNT 可数名词","cn":"面巾纸;手巾纸","en":"A tissue is a piece of thin soft paper that you use to blow your nose.","ex":{"en":"...a box of tissues.","cn":"一盒面巾纸"}}]},"media":{"uk":"media/uk/tissue__gb_1.mp3","us":"media/us/tissue__us_1.mp3","img":["media/ldoce/img/paper_tissues.jpg"]},"examples":[{"en":"muscle/brain/nerve, etc. tissue","cn":"肌肉、大脑、神经等组织"},{"en":"scar tissue","cn":"瘢痕组织"}]},"tie":{"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/trousers.jpg","media/ldoce/img/neck_tie.jpg"],"uk":"media/uk/tie__gb_1.mp3","us":"media/us/tie__us_1.mp3"},"oxford":{"phon":"taɪ","pos":"verb","senses":[{"en":"to attach or hold two or more things together using string, rope, etc.; to fasten somebody/something with string, rope, etc.","cn":"（用线、绳等）系，拴，绑，捆","g":"[transitive]","sc":"fasten with string/rope","ex":{"en":"She tied the newspapers in a bundle.","cn":"她把报纸扎成一捆。"}},{"en":"to fasten something to or around something else","cn":"将…系在…上；束紧；系牢；捆绑","g":"[transitive]","sc":"fasten with string/rope","ex":{"en":"She tied a label on to the suitcase.","cn":"她把签条系在衣箱上。"}},{"en":"to make a knot in a piece of string, rope, etc.","cn":"（在线、绳等上）打结，系扣","g":"[transitive]","sc":"fasten with string/rope","ex":{"en":"to tie a ribbon","cn":"系丝带"}},{"en":"to be closed or fastened with a knot, etc.","cn":"打结系牢；系上","g":"[intransitive]","sc":"fasten with string/rope","ex":{"en":"The skirt ties at the waist.","cn":"裙子在腰部束紧。"}},{"en":"to connect or link somebody/something closely with somebody/something else","cn":"连接；联合；使紧密结合","g":"[transitive, usually passive]","sc":"connect/link","ex":{"en":"Pay increases are tied to inflation.","cn":"提高工资和通货膨胀紧密相关。"}},{"en":"to limit somebody's freedom to act and make them unable to do everything they want to","cn":"束缚；约束；限制","g":"[transitive, usually passive]","sc":"limit","ex":{"en":"to be tied by a contract","cn":"受合同的约束"}},{"en":"to have the same number of points","cn":"打成平局；得分相同","g":"[intransitive, transitive]","sc":"in game/competition","ex":{"en":"England tied 2–2 with Germany in the first round.","cn":"在第一轮比赛中英格兰队与德国队以 2:2 打成平局。"}},{"en":"to join notes with a tie","cn":"用延音线连接（音符）","g":"[transitive]","sc":"music"},{"en":"a long, narrow piece of cloth worn around the neck, especially by men, with a knot in front","cn":"领带","lab":"North American English also","sc":"clothes","ex":{"en":"He was dressed impeccably in a suit and tie.","cn":"他穿西装打领带十分得体。"},"pos":"noun"},{"en":"a piece of string or wire used for fastening or tying something","cn":"绳子；金属丝；线","sc":"for fastening","ex":{"en":"ties for closing plastic bags","cn":"封塑料袋用的捆扎绳"},"pos":"noun"},{"en":"a strong connection between people or organizations","cn":"联系；关系；纽带","g":"[usually plural]","sc":"connection","ex":{"en":"family ties","cn":"家族关系"},"pos":"noun"},{"en":"a thing that limits somebody’s freedom of action","cn":"束缚；约束；限制；牵累","sc":"limit","ex":{"en":"He was still a young man and he did not want any ties.","cn":"他还年轻，不想有任何束缚。"},"pos":"noun"},{"en":"a situation in a game or competition when two or more players have the same score","cn":"平局；得分相同；不分胜负","sc":"in game/competition","ex":{"en":"The match ended in a tie.","cn":"这场比赛以平局结束。"},"pos":"noun"},{"en":"a sports match, especially a football (soccer) match, that is part of a larger competition","cn":"（尤指足球）淘汰赛","lab":"British English","sc":"in game/competition","ex":{"en":"the first leg of the tie between Leeds and Roma","cn":"利兹队和罗马队在杯赛淘汰赛中的第一轮比赛"},"pos":"noun"},{"en":"a curved line written over two notes of the same pitch (= how high or low a note is) to show that they are to be played or sung as one note","cn":"延音线；延音连接线","sc":"music","pos":"noun"},{"en":"one of the heavy pieces of wood or concrete on which the rails (= metal bars) on a railway track are laid","cn":"（铁路）轨枕，枕木","lab":"North American English","sc":"on railway","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"系；扣；捆；将…打成结","en":"If you tie two things together or tie them, you fasten them together with a knot.","ex":{"en":"He tied the ends of the plastic bag together","cn":"他把塑料袋的两头系在了一起。"}},{"pos":"VERB 动词","cn":"(用绳索)捆扎，固定，系牢","en":"If you tie something or someone in a particular place or position, you put them there and fasten them using rope or string.","ex":{"en":"He had tied the dog to one of the trees near the canal","cn":"他把狗拴在了沟旁的一棵树上。"}},{"pos":"VERB 动词","cn":"用（绳子或布）捆扎","en":"If you tie a piece of string or cloth around something or tie something with a piece of string or cloth, you put the piece of string or cloth around it and fasten the ends together.","ex":{"en":"She tied her scarf over her head","cn":"她把头巾围在头上。"}},{"pos":"VERB 动词","cn":"打(结或蝴蝶结)；将…打成(结或蝴蝶结)","en":"If you tie a knot or bow in something or tie something in a knot or bow, you fasten the ends together.","ex":{"en":"He took a short length of rope and swiftly tied a slip knot","cn":"他拿起一小截绳子，飞快地打了个活结。"}},{"pos":"V-ERG 及物/不及物动词","cn":"打结系牢；扣结实","en":"When you tie something or when something ties, you close or fasten it using a bow or knot.","ex":{"en":"He pulled on his heavy suede shoes and tied the laces.","cn":"他穿上厚厚的软皮鞋，系上鞋带。"}},{"pos":"N-COUNT 可数名词","cn":"领带；领结","en":"A tie is a long narrow piece of cloth that is worn round the neck under a shirt collar and tied in a knot at the front. Ties are worn mainly by men.","ex":{"en":"Jason had taken off his jacket and loosened his tie.","cn":"贾森已经脱下夹克，松开了领带。"}},{"pos":"VERB 动词","cn":"（使）紧密相连；（使）关系密切","en":"If one thing is tied to another or two things are tied, the two things have a close connection or link.","ex":{"en":"Their cancers are not so clearly tied to radiation exposure","cn":"他们的癌症是否和接触放射线有关还不太清楚。"}},{"pos":"VERB 动词","cn":"束缚;限制","en":"If you are tied to a particular place or situation, you are forced to accept it and cannot change it.","ex":{"en":"They had children and were consequently tied to the school holidays","cn":"他们有孩子，当然就受学校假期的束缚。"}},{"pos":"N-COUNT 可数名词","cn":"联系;关系","en":"Ties are the connections you have with people or a place.","ex":{"en":"Quebec has always had particularly close ties to France","cn":"魁北克和法国一向关系特别紧密。"}},{"pos":"N-COUNT 可数名词","cn":"枕木；轨枕","en":"Railroad ties are large heavy beams that support the rails of a railway track."},{"pos":"V-RECIP 相互动词","cn":"得分相同;旗鼓相当","en":"If two people tie in a competition or game or if they tie with each other, they have the same number of points or the same degree of success.","ex":{"en":"Both teams had tied on points and goal difference","cn":"两支队伍得分和净胜球都相当。"}},{"pos":"N-COUNT 可数名词","cn":"(体育比赛的)淘汰赛","en":"In sport, a tie is a match that is part of a competition. The losers leave the competition and the winners go on to the next round.","ex":{"en":"They'll meet the winners of the first round tie.","cn":"他们将迎战第一轮淘汰赛中的胜者。"}},{"pos":"See also:","cn":"","en":"→see: ; to tie the knot→see: ; to tie yourself in knots→see: ;"},{"pos":"","cn":"","en":"相关词组：tie down tie in with tie up tie up with"}]},"examples":[{"en":"England tied 2–2 with Germany in the first round.","cn":"在第一轮比赛中英格兰队与德国队以 2:2 打成平局。"},{"en":"The house is tied to the job, so we'll have to move when I retire.","cn":"这房子是为工作提供的，所以我退休后我们就得搬家。"}]},"tilted":{"oxford":{"phon":"tɪlt","pos":"verb","senses":[{"en":"to move, or make sth move, into a position with one side or end higher than the other （","cn":"使）倾斜，倾侧"},{"en":"to make sth/sb change slightly so that one particular opinion, person, etc. is preferred or more likely to succeed than another; to change in this way","cn":"使倾向于；使向 … 倾斜；偏向"}]}},"tidies":{"oxford":{"phon":"ˈtaɪdi","pos":"adjective","senses":[{"en":"( especially BrE ) arranged neatly and with everything in order","cn":"整洁的；整齐的；井然有序的；井井有条的"},{"en":"( especially BrE ) keeping things neat and in order","cn":"爱整洁的；爱整齐的"}]}},"tips":{"oxford":{"phon":"tɪp","pos":"noun","senses":[{"en":"the thin pointed end of sth","cn":"尖端；尖儿；端"},{"en":"a small part that fits on or over the end of sth （","cn":"装在顶端的）小部件"}]}},"tinged":{"oxford":{"phon":"tɪndʒ","pos":"verb","senses":[{"en":"to add a small amount of colour to sth （","cn":"轻微地）给 … 着色，给 … 染色"},{"en":"to add a small amount of a particular emotion or quality to sth","cn":"使略带 … 感情（或性质）"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"略带有…色的","en":"If something is tinged with a particular colour, it has a small amount of that colour in it.","ex":{"en":"His dark hair was just tinged with grey","cn":"他的黑发略有点花白。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"显出(某种情感或品质)的","en":"If something is tinged with a particular feeling or quality, it has or shows a small amount of that feeling or quality. 略","ex":{"en":"Her homecoming was tinged with sadness.","cn":"她的返乡略带一丝哀伤。"}}]},"media":{"uk":"media/ldoce/hwd/bre/2/tinged0205.mp3","us":"media/ldoce/hwd/ame/6/laadtinged.mp3"},"examples":[{"en":"His voice was tinged with sadness and regret.","cn":"他的声音里带有一丝悲伤和遗憾。"},{"en":"white blossom tinged with pink","cn":"略带粉红色的白花"}]},"tipped":{"oxford":{"phon":"tɪp","pos":"noun","senses":[{"en":"the thin pointed end of sth","cn":"尖端；尖儿；端"},{"en":"a small part that fits on or over the end of sth （","cn":"装在顶端的）小部件"}]}},"ties":{"oxford":{"phon":"taɪ","pos":"verb","senses":[{"en":"to attach or hold two or more things together using string, rope, etc; to fasten sb/sth with string, rope, etc. （","cn":"用线、绳等）系，拴，绑，捆，束"},{"en":"to fasten sth to or around sth else","cn":"将 … 系在 … 上；束紧；系牢；捆绑"}]}},"tipping":{"oxford":{"phon":"tɪp","pos":"noun","senses":[{"en":"the thin pointed end of sth","cn":"尖端；尖儿；端"},{"en":"a small part that fits on or over the end of sth （","cn":"装在顶端的）小部件"}]}},"tiddler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小鱼","en":"A tiddler is a very small fish of any kind."},{"pos":"N-COUNT 可数名词","cn":"小人物;小玩意儿","en":"If you refer to a person or thing as a tiddler, you mean that they are very unimportant or small, especially when compared to other people or things of the same type.","ex":{"en":"On a world scale the earthquake was a tiddler.","cn":"从全球范围看，这次地震算不了什么。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small fish","cn":"很小的鱼"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41tiddler.mp3","us":"media/ldoce/hwd/ame/a/ld41tiddler.mp3"},"oxford":{"phon":"ˈtɪdlə(r)","pos":"noun","senses":[{"en":"a very small fish","cn":"小鱼"}]}},"tidal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"潮汐的;受潮汐影响的","en":"Tidal means relating to or produced by tides.","ex":{"en":"The tidal stream or current gradually decreases in the shallows","cn":"浅滩上的潮水逐渐退去。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the regular rising and falling of the sea","cn":"潮汐的﹐潮水的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41tidal.mp3","us":"media/ldoce/hwd/ame/e/tidal.mp3"},"examples":[{"en":"tidal forces","cn":"潮汐力"},{"en":"a tidal river","cn":"感潮河"}],"oxford":{"phon":"ˈtaɪdl","pos":"adjective","senses":[{"en":"connected with tides (= the regular rise and fall of the sea)","cn":"潮汐的；有潮的","ex":{"en":"tidal forces/energy","cn":"潮汐力／能"}}]}},"timer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"计时器;定时器","en":"A timer is a device that measures time, especially one that is part of a machine and causes it to start or stop working at specific times.","ex":{"en":"...electronic timers that automatically switch on the lights when it gets dark.","cn":"光线一暗就自动开灯的电子定时器"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instrument that you use to measure time, when you are doing something such as cooking","cn":"定时器"},{"en":"someone who works part or all of a normal working week","cn":"兼职人员/全职人员"}]},"media":{"uk":"media/ldoce/hwd/bre/6/timer0205.mp3","us":"media/ldoce/hwd/ame/c/timer.mp3","img":["media/thumb/timer.jpg"]},"examples":[{"en":"an oven timer","cn":"烤箱定时器"},{"en":"Set the timer on the cooker for three minutes.","cn":"把炉子上的定时器设定为三分钟。"}],"oxford":{"phon":"ˈtaɪmə(r)","pos":"noun","senses":[{"en":"a device that is used to measure the time that something takes; a device that starts or stops a machine working at a particular time","cn":"时计；计时器；跑表；定时器","ex":{"en":"an oven timer","cn":"烤箱定时器"}}]}},"tingle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"感到刺痛","en":"When a part of your body tingles, you have a slight stinging feeling there.","ex":{"en":"The backs of his thighs tingled.","cn":"他大腿后侧感到刺痛。"}},{"pos":"VERB 动词","cn":"强烈地感到;激动","en":"If you tingle with a feeling such as excitement, you feel it very strongly.","ex":{"en":"She tingled with excitement","cn":"她激动不已。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a part of your body tingles, you feel a slight stinging feeling, especially on your skin 〔","cn":"尤指皮肤〕感到刺痛﹐刺痒"},{"en":"to feel excitement, fear etc very strongly","cn":"感到很激动/充满恐惧/充满期待等"}]},"media":{"uk":"media/ldoce/hwd/bre/f/tingle0205.mp3","us":"media/ldoce/hwd/ame/1/tingle.mp3"},"examples":[{"en":"The cold air made her face tingle.","cn":"冷空气冻得她的脸发痛。"},{"en":"She was still tingling with excitement.","cn":"她仍然兴奋不已。"}],"oxford":{"phon":"ˈtɪŋɡl","pos":"verb","senses":[{"en":"to feel as if a lot of small sharp points are pushing into it","cn":"感到刺痛","g":"[intransitive]","ex":{"en":"The cold air made her face tingle.","cn":"冷空气冻得她的脸发痛。"}},{"en":"to feel an emotion strongly","cn":"强烈地感到","g":"[intransitive]","ex":{"en":"She was still tingling with excitement.","cn":"她仍然兴奋不已。"}},{"en":"a slight uncomfortable feeling in a part of your body","cn":"刺痛感；轻微不适感","ex":{"en":"As she warmed her hands by the fire, she felt a tingle in her fingers.","cn":"当她在火边暖手时，她感到手指有些刺痛。"},"pos":"noun"},{"en":"an exciting or uncomfortable feeling of emotion","cn":"激动感；兴奋感；震颤","ex":{"en":"to feel a tingle of excitement","cn":"感到一阵激动"},"pos":"noun"}]}},"titled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有称号的;有头衔的;有爵位的","en":"Someone who is titled has a title such as 'Lord', 'Lady', 'Sir', or 'Princess' before their name, showing that they have a high rank in society.","ex":{"en":"Her mother was a titled lady.","cn":"她母亲是个有爵位的贵夫人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a title in the aristocracy , such as ‘lord’, duke , earl etc","cn":"有贵族头衔的﹐有爵位的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdetitled.mp3","us":"media/ldoce/hwd/ame/6/titled.mp3"},"oxford":{"phon":"ˈtaɪtld","pos":"adjective","senses":[{"en":"having a title such as Lord, Lady, etc.","cn":"有头衔的；有爵位的"}]}},"tidings":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"消息","en":"You can use tidings to refer to news that someone tells you.","ex":{"en":"He hated always to be the bearer of bad tidings","cn":"他讨厌总是带去坏消息。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"news","cn":"消息"}]},"vocab":{"pos":"n","senses":[{"en":"Tidings is an old-fashioned word for recent news. If someone says \"I bring you good tidings !\" it means they have information to share that you'll probably like."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41tidings.mp3","us":"media/ldoce/hwd/ame/a/tidings.mp3"},"examples":[{"en":"I am the bearer of good tidings.","cn":"我带来了好消息。"},{"en":"He brought glad tidings.","cn":"他带来了喜讯。"}],"oxford":{"phon":"ˈtaɪdɪŋz","pos":"noun","senses":[{"en":"news","cn":"消息；音讯；音信","ex":{"en":"I am the bearer of good tidings.","cn":"我带来了好消息。"}}]}},"tithe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(定期定量缴纳给教会、慈善机构等的)什一税，捐税，捐款","en":"A tithe is a fixed amount of money or goods that is given regularly in order to support a church, a priest, or a charity."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a particular amount that some Christians give to their church 〔","cn":"基督徒给教会的〕捐款"},{"en":"a tax paid to the church in the past 〔","cn":"旧时支付给基督教会的〕什一税"}]},"vocab":{"pos":"n v","senses":[{"en":"To tithe is to make a contribution equal to one-tenth of your income, usually to a church or religious institution. You probably always tithe , even in years when your finances are very tight."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41tithe.mp3","us":"media/ldoce/hwd/ame/0/tithe.mp3"},"oxford":{"phon":"taɪð","pos":"noun","senses":[{"en":"(in the past) a tenth of the goods that somebody produced or the money that they earned, which was paid as a tax to support the Church","cn":"（旧时按固定比例给教会的）什一税"},{"en":"(in some Christian Churches today) a tenth of a person’s income that they give to the Church","cn":"（现在某些教友按收入的十分之一给基督教教会的）什一捐献"}]}},"tine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(叉等的)尖头，尖齿","en":"The tines of something such as a fork are the long pointed parts."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pointed part of something that has several points, for example a fork 〔","cn":"叉等的〕尖头﹐尖齿"}]},"vocab":{"pos":"n","senses":[{"en":"A tine is a prong, or a point. When you were little, you may have lined up your peas on the tines of your fork despite your parents telling you not to play with your food."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41tine.mp3","us":"media/ldoce/hwd/ame/1/tine.mp3"},"oxford":{"phon":"taɪn","pos":"noun","senses":[{"en":"any of the points or sharp parts of, for example, a fork or the antlers of a deer","cn":"（叉子等的）尖头，尖齿；（鹿角的）分叉"}]}},"ticker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"心;心脏","en":"Your ticker is your heart."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your heart","cn":"心脏"},{"en":"a special machine that prints or shows the price of company stock s as they go up and down 〔","cn":"股票行情〕自动收录机﹐电子显示器"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41ticker.mp3","us":"media/ldoce/hwd/ame/0/ticker.mp3"},"oxford":{"phon":"ˈtɪkə(r)","pos":"noun","senses":[{"en":"a line of text containing news that passes across the screen of a computer or television","cn":"（计算机或电视屏幕上的）滚动新闻条"},{"en":"a person’s heart","cn":"（人的）心脏","lab":"old-fashioned, informal，，","ex":{"en":"‘There’s nothing wrong with the old ticker,’ he said.","cn":"“旧的股票行情没有任何问题，”他说。"}}]}},"tirade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"激愤的长篇演说;长篇的批评性发言","en":"A tirade is a long angry speech in which someone criticizes a person or thing.","ex":{"en":"She launched into a tirade against the policies that ruined her business","cn":"她就造成自己企业破产的政策发表了激愤的长篇演说。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long angry speech criticizing someone or something","cn":"抨击性的长篇讲话"}]},"vocab":{"pos":"n","senses":[{"en":"A tirade is a speech, usually consisting of a long string of violent, emotionally charged words. Borrow and lose your roommate’s clothes one too many times, and you can bet you’ll be treated to a heated tirade ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/tirade0205.mp3","us":"media/ldoce/hwd/ame/c/tirade.mp3"},"examples":[{"en":"She launched into a tirade of abuse against politicians.","cn":"她发表了长篇演说，愤怒地谴责政客。"},{"en":"He launched into a tirade against the church.","cn":"他开始大发议论﹐抨击教会。"}],"oxford":{"phon":"taɪˈreɪd","pos":"noun","senses":[{"en":"a long angry speech criticizing somebody/something or accusing somebody of something","cn":"（批评或指责性的）长篇激烈讲话","ex":{"en":"She launched into a tirade of abuse against politicians.","cn":"她发表了长篇演说，愤怒地谴责政客。"}}]}},"tic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(面部或身体局部的)抽搐，痉挛","en":"If someone has a tic, a part of their face or body keeps making a small uncontrollable movement, for example because they are tired or have a nervous illness.","ex":{"en":"...people with nervous tics","cn":"患神经性痉挛的人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden movement of a muscle in your face, that you cannot control 〔","cn":"面部肌肉的〕抽搐"}]},"media":{"uk":"media/ldoce/hwd/bre/1/tic0205.mp3","us":"media/ldoce/hwd/ame/4/tic1.mp3"},"oxford":{"phon":"tɪk","pos":"noun","senses":[{"en":"a sudden, quick movement of a muscle, especially in your face or head, that you cannot control","cn":"（尤指面部或头部肌肉的）抽搐","ex":{"en":"a nervous tic","cn":"神经抽搐"}}]}},"timekeeping":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"守时","en":"If you talk about someone's timekeeping, you are talking about how good they are at arriving in time for things.","ex":{"en":"I am trying to improve my timekeeping","cn":"我努力使自己变得更加守时。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(比赛的)计时，测定时间","en":"Timekeeping is the process or activity of timing an event or series of events.","ex":{"en":"Who did the timekeeping?","cn":"谁负责计时？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who officially records the times taken to do something, especially at a sports event","cn":""},{"en":"someone who is good or bad at arriving at work at the right time","cn":""},{"en":"a watch or clock that is good or bad at showing the right time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/timekeeper0205.mp3","us":"media/ldoce/hwd/ame/4/timekeeper.mp3"},"oxford":{"phon":"ˈtaɪmkiːpɪŋ","pos":"noun","senses":[{"en":"a person’s ability to arrive in time for things, especially work","cn":"（尤指上班的）准时，守时","ex":{"en":"Poor timekeeping and absenteeism will not be tolerated.","cn":"不遵守时间和缺勤是不能容忍的。"}},{"en":"the activity of recording the time something takes","cn":"计时","ex":{"en":"In 1967 the rotation of the earth was abandoned as the basic source of timekeeping.","cn":"1967年，地球自转作为计时的基本来源被放弃。"}}]}},"tipple":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"常喝的酒","en":"A person's tipple is the alcoholic drink that they usually drink.","ex":{"en":"My favourite tipple is a glass of port.","cn":"我最喜欢喝的酒是波尔图葡萄酒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone’s favourite alcoholic drink","cn":"某人最爱喝的酒"}]},"vocab":{"pos":"v n","senses":[{"en":"Use the verb tipple when you want to show that someone drinks moderately but regularly. During Prohibition in the 1920s it was illegal to tipple but today you can tipple almost anywhere — as long as you are 21."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41tipple.mp3","us":"media/ldoce/hwd/ame/e/ld41tipple.mp3"},"examples":[{"en":"His favourite tipple was rum and lemon.","cn":"他最爱喝的饮料是朗姆酒加柠檬汁。"}],"oxford":{"phon":"ˈtɪpl","pos":"noun","senses":[{"en":"an alcoholic drink","cn":"酒","ex":{"en":"His favourite tipple was rum and lemon.","cn":"他最爱喝的饮料是朗姆酒加柠檬汁。"}},{"en":"to drink alcohol","cn":"饮酒","pos":"verb"}]}},"tiller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(船的)舵柄","en":"The tiller of a boat is a handle that is fixed to the rudder. It is used to turn the rudder, which then steers the boat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long handle fastened to the rudder (= part that controls the direction ) of a boat 〔","cn":"船的〕舵柄"}]},"vocab":{"pos":"1 n 2 n 3 n v","senses":[{"en":"The tiller is what steers a boat — specifically, the handle attached to the rudder. Tillers are generally found on smaller boats because it would take too much force to steer larger ships with hand tillers ."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41tiller.mp3","us":"media/ldoce/hwd/ame/0/tiller.mp3"},"oxford":{"phon":"ˈtɪlə(r)","pos":"noun","senses":[{"en":"a bar that is used to turn the rudder of a small boat in order to control the direction in which it moves","cn":"（小船的）舵柄"}]}},"timeless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"永久的;恒久美好的;不受时间影响的","en":"If you describe something as timeless, you mean that it is so good or beautiful that it cannot be affected by changes in society or fashion.","ex":{"en":"There is a timeless quality to his best work.","cn":"他最好的作品不会因时间流逝而逊色。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"music, literature, art etc, that is timeless still seems important and interesting even though it was written or made a long time ago","cn":""},{"en":"immortal words, lines etc are famous and are remembered for a long time after they are written or spoken","cn":""},{"en":"a classic book, film, design etc is one that is important or special and remains popular for a long time","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something timeless is a classic of some sort that is unchanged by time. It's just as good or true now as when it was created."}]},"media":{"uk":"media/ldoce/hwd/bre/1/timeless0205.mp3","us":"media/ldoce/hwd/ame/2/timeless.mp3"},"examples":[{"en":"her timeless beauty","cn":"她的永恒的美丽"},{"en":"timeless eternity","cn":"万古长存"}],"oxford":{"phon":"ˈtaɪmləs","pos":"adjective","senses":[{"en":"not appearing to be affected by the process of time passing or by changes in fashion","cn":"不受时间影响的；无时间性的；永不过时的","ex":{"en":"her timeless beauty","cn":"她的永恒的美丽"}},{"en":"existing or continuing forever","cn":"永存的；永远的；永恒的；永久的","ex":{"en":"timeless eternity","cn":"万古长存"}}]}},"tiptoe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"踮起脚走;蹑手蹑脚地走","en":"If you tiptoe somewhere, you walk there very quietly without putting your heels on the floor when you walk.","ex":{"en":"She slipped out of bed and tiptoed to the window.","cn":"她溜下床，蹑手蹑脚地走到窗户旁边。"}},{"pos":"PHRASE 短语","cn":"踮着脚","en":"If you do something on tiptoe or on tiptoes, you do it standing or walking on the front part of your foot, without putting your heels on the ground.","ex":{"en":"She leaned her bike against the stone wall and stood on tiptoe to peer over it.","cn":"她把自行车斜靠在石墙上，踮起脚往墙内张望。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be on your feet in an upright position","cn":""},{"en":"to stand rather than be sitting, lying down, or kneeling","cn":""},{"en":"to be standing, especially for a long time, with the result that you feel tired - use this especially about people who have to stand and walk a lot in their jobs","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/tiptoe_v0205.mp3","us":"media/ldoce/hwd/ame/0/tiptoe1.mp3"},"examples":[{"en":"We crept around on tiptoes so as not to disturb him.","cn":"我们蹑手蹑脚地在周围走动，以免惊动他。"},{"en":"She had to stand on tiptoe to reach the top shelf.","cn":"她得踮着脚才能够到顶层搁架。"}],"oxford":{"phon":"ˈtɪptəʊ","pos":"verb","senses":[{"en":"to walk using the front parts of your feet only, so that other people cannot hear you","cn":"踮着脚走；蹑手蹑脚地走","ex":{"en":"I tiptoed over to the window.","cn":"我踮着脚走到窗前。"}}]}},"timorous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"胆怯的;胆小的;易受惊吓的","en":"If you describe someone as timorous, you mean that they are frightened and nervous of other people and situations.","ex":{"en":"He is a reclusive, timorous creature.","cn":"他是个离群索居、胆小羞怯的家伙。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不果断的;缩手缩脚的","en":"If you describe someone's actions or decisions as timorous, you are criticizing them for being too cautious or weak, because the person is not very confident and is worried about the possible consequences of their actions.","ex":{"en":"Some delegates believe the final declaration is likely to be too timorous.","cn":"一些代表认为最后的声明可能不够强硬。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"lacking confidence and easily frightened","cn":"胆怯的﹔缺乏自信的﹔易受惊吓的"}]},"vocab":{"pos":"adj","senses":[{"en":"A timorous person is timid or shy, like your timorous friend who likes to hang out with close pals but gets nervous around big groups of new people."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41timorous.mp3","us":"media/ldoce/hwd/ame/5/timorous.mp3"},"examples":[{"en":"She was no helpless, timorous female.","cn":"她绝不是柔弱胆怯的女性。"}],"oxford":{"phon":"ˈtɪmərəs","pos":"adjective","senses":[{"en":"nervous and easily frightened","cn":"羞怯的；胆怯的；畏怯的"}]}},"tiddly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"微醉的","en":"If someone is tiddly, they are slightly drunk."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很小的","en":"If you describe a thing as tiddly, you mean that it is very small.","ex":{"en":"...a tiddly picture.","cn":"一张小图"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"slightly drunk","cn":"微醉的"},{"en":"very small","cn":"极小的﹐小型的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/tiddly0205.mp3","us":"media/ldoce/hwd/ame/6/ld41tiddly.mp3"},"examples":[{"en":"a tiddly little insect","cn":"一只很小的昆虫"}],"oxford":{"phon":"ˈtɪdli","pos":"adjective","senses":[{"en":"slightly drunk","cn":"微醉的；略有醉意的","ex":{"en":"I feel a bit tiddly.","cn":"我感觉有点醉意。"}},{"en":"very small","cn":"微小的","ex":{"en":"All I got to eat was a tiddly little biscuit.","cn":"我只吃一块小小的饼干。"}}]}},"timepiece":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钟;表;计时器","en":"A timepiece is a clock, watch, or other device that measures and shows time."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clock or watch","cn":"计时器﹔钟﹔表"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41timepiece.mp3","us":"media/ldoce/hwd/ame/5/timepiece.mp3"},"oxford":{"phon":"ˈtaɪmpiːs","pos":"noun","senses":[{"en":"a clock or watch","cn":"钟；表"}]}},"ticklish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(问题、情况、任务)艰难的，难处理的;棘手的","en":"A ticklish problem, situation, or task is difficult and needs to be dealt with carefully.","ex":{"en":"So car makers are faced with the ticklish problem of how to project products at new buyers.","cn":"因此，汽车制造商面临着怎样向新顾客树立产品形象的大难题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怕痒的;怕胳肢的","en":"Someone who is ticklish is sensitive to being tickled, and laughs as soon as you tickle them.","ex":{"en":"This massage method is not recommended for anyone who is very ticklish.","cn":"这种按摩法不推荐给怕痒的人使用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is ticklish laughs a lot when you tickle them","cn":"易痒的﹐怕痒的"},{"en":"a ticklish situation or problem is difficult and must be dealt with carefully, especially because you may upset people 〔","cn":"情况或问题〕需小心应对的﹐棘手的"},{"en":"a ticklish cough is in your throat rather than in your chest 〔","cn":"咳嗽时〕喉咙发痒的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41ticklish.mp3","us":"media/ldoce/hwd/ame/3/ticklish.mp3"},"examples":[{"en":"Are you ticklish?","cn":"你怕痒吗？"},{"en":"a dry ticklish cough","cn":"喉咙发痒的干咳"}],"oxford":{"phon":"ˈtɪklɪʃ","pos":"adjective","senses":[{"en":"sensitive to being tickled","cn":"怕痒的；易痒的","ex":{"en":"Are you ticklish?","cn":"你怕痒吗？"}},{"en":"difficult to deal with, and possibly embarrassing","cn":"难对付的；难处理的；棘手的","lab":"informal","ex":{"en":"It's quite a ticklish problem deciding how many people to invite to the wedding.","cn":"决定邀请多少人参加婚礼是一个相当棘手的问题。"}},{"en":"that makes your throat painful","cn":"使喉咙疼痛的","ex":{"en":"a dry ticklish cough","cn":"喉咙不舒服的干咳"}}]}},"title-holder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（体育赛事的）冠军保持者;冠军","en":"The title-holder is the person who most recently won a sports competition that is held regularly.","ex":{"en":"Kasparov became the youngest world title-holder at 22.","cn":"卡斯帕罗夫 22 岁时成为最年轻的世界冠军。"}}]},"examples":[{"en":"the current Olympic title-holder","cn":"本届奥林匹克运动会冠军"}],"oxford":{"phon":"ˈtaɪtl həʊldə(r)","pos":"noun","senses":[{"en":"a person or team that has defeated all the other people or teams taking part in an important competition","cn":"冠军；冠军得主","ex":{"en":"the current Olympic title-holder","cn":"本届奥林匹克运动会冠军"}},{"en":"the legal owner of something","cn":"法定所有人；合法所有人","lab":"specialist, North American English，，"}]}},"titan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"巨子;巨人;成就非凡的人","en":"If you describe someone as a titan of a particular field, you mean that they are very important and powerful or successful in that field.","ex":{"en":"...the country's two richest business titans.","cn":"该国最富有的两位商业巨子"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very strong or important person","cn":"巨人﹐大力士﹔泰斗﹐大师"}]},"vocab":{"pos":"n","senses":[{"en":"A titan is an extremely important person. Albert Einstein was a titan in the world of science."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41titan.mp3","us":"media/ldoce/hwd/ame/1/titan.mp3"},"oxford":{"phon":"ˈtaɪtn","pos":"noun","senses":[{"en":"a person who is very large, strong, intelligent or important","cn":"巨人；高人；伟人","ex":{"en":"a battle between the titans of American football","cn":"美式足球巨头之间的战斗"}}]}},"timeline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指历史事件)年表","en":"A timeline is a visual representation of a sequence of events, especially historical events.","ex":{"en":"A unique 13,000-word timeline runs through the full-colour volume, detailing events from the Earth's creation to the present day.","cn":"一份独一无二的 13,000 词的年表贯穿彩印卷的始终，详细记述了从地球诞生到今天发生的重大历史事件。"}},{"pos":"N-COUNT 可数名词","cn":"时间期限","en":"A timeline is the length of time that a project is expected to take.","ex":{"en":"Use your deadlines to establish the timeline for your research plan.","cn":"依据最后期限来确定研究计划的时间表。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a detailed plan of what someone is going to do and when they will do it, especially someone important","cn":""},{"en":"a written list that shows the exact times when something will happen, for example when planes or buses leave, or when classes at school take place","cn":""},{"en":"a plan that shows the order of activities at a ceremony, sports meeting, public event etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A timeline is a list of important events arranged in the order in which they happened. You might write out a timeline of Civil War battles when you're studying for a big history test."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41timeline.mp3","us":"media/ldoce/hwd/ame/b/laadtimeline.mp3"},"examples":[{"en":"The timeline for the project is optimistic.","cn":"项目的进程十分乐观。"}],"oxford":{"phon":"ˈtaɪmlaɪn","pos":"noun","senses":[{"en":"a horizontal line that is used to represent time, with the past towards the left and the future towards the right","cn":"时间线，时线（用以表示时间的水平线，左边表示过去，右边表示未来）"},{"en":"a list of all somebody’s social media activity on a particular website or software program in the order in which it happened, with the most recent activity shown at the beginning of the list","cn":"（网站或软件程序中的）时间轴，时间线（显示某人在社交媒体的活动，按时间倒序排列）","ex":{"en":"These days, your Facebook timeline can serve as a digital scrapbook of your life.","cn":"如今，您的 Facebook 时间线可以作为您生活的数字剪贴簿。"}}]}},"titillate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"逗引;使兴奋;(尤指在性方面)挑逗","en":"If something titillates someone, it pleases and excites them, especially in a sexual way.","ex":{"en":"The pictures were not meant to titillate audiences.","cn":"图片本意不是为了挑逗观众。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel sexually excited","cn":""},{"en":"if pictures, stories etc in newspapers and books titillate people, they are deliberately intended to make people feel slightly sexually excited","cn":""},{"en":"if a picture or a story titillates someone, it makes them feel sexually interested","cn":"使感到性兴奋"}]},"vocab":{"pos":"v","senses":[{"en":"A juicy steak may titillate your taste buds, or sexy images in a foreign film may titillate your desire. Titillate means to excite someone's imagination, especially in a sexual way."}]},"media":{"uk":"media/ldoce/hwd/bre/3/titillate0205.mp3","us":"media/ldoce/hwd/ame/a/titillate.mp3"},"examples":[{"en":"a story intended to titillate the imagination of the public","cn":"意欲煽动公众想像力的故事"},{"en":"titillating pictures","cn":"煽动情欲的图画"}],"oxford":{"phon":"ˈtɪtɪleɪt","pos":"verb","senses":[{"en":"to cause somebody to be interested or excited, especially in a sexual way","cn":"使兴奋；煽情；煽动情欲","ex":{"en":"titillating pictures","cn":"煽动情欲的图画"}}]}},"tinder":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"火绒;引火物;火媒","en":"Tinder consists of small pieces of something dry, especially wood or grass, that burns easily and can be used for lighting a fire."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"dry material that burns easily and can be used for lighting fires","cn":"引火物﹐火绒﹐火媒"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41tinder.mp3","us":"media/ldoce/hwd/ame/b/tinder.mp3"},"examples":[{"en":"The fire started late Saturday in tinder-dry grass near the Snake River.","cn":"大火是星期六晚些时候在斯内克河附近干枯的草地上燃起的。"}],"oxford":{"phon":"ˈtɪndə(r)","pos":"noun","senses":[{"en":"dry material, especially wood or grass, that burns easily and can be used to light a fire","cn":"引火物；火绒；火种","ex":{"en":"The fire started late Saturday in tinder-dry grass near the Snake River.","cn":"大火是星期六晚些时候在斯内克河附近干枯的草地上燃起的。"}}]}},"tipsy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"微醉的；微醺的","en":"If someone is tipsy, they are slightly drunk.","ex":{"en":"I'm feeling a bit tipsy.","cn":"我感觉有点微醉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having drunk too much alcohol so that your behaviour and mental processes are affected","cn":""},{"en":"slightly drunk","cn":"微醉的"},{"en":"drunk – this word is very common in spoken British English, but it is not polite","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use tipsy to describe a person who's just slightly drunk. If you've ever been to a wedding reception, you've probably seen a tipsy person."}]},"media":{"uk":"media/ldoce/hwd/bre/e/tipsy0205.mp3","us":"media/ldoce/hwd/ame/6/tipsy.mp3"},"oxford":{"phon":"ˈtɪpsi","pos":"adjective","senses":[{"en":"slightly drunk","cn":"微醉的；略有醉意的"}]}},"tinny":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尖细的;刺耳的","en":"If you describe a sound as tinny, you mean that it has an irritating, high-pitched quality.","ex":{"en":"He could hear the tinny sound of a radio playing a pop song.","cn":"他能听到收音机播放流行歌曲的刺耳声音。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"质量差的;劣质金属制成的","en":"If you use tinny to describe something such as a cheap car, you mean that it is made of thin metal and is of poor quality.","ex":{"en":"It is one of the cheapest cars on the market, with tinny bodywork.","cn":"那是市场上最廉价的汽车之一，车身用劣质金属制成。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"near the top range of sounds that humans can hear - use this about sounds, voices, or musical notes","cn":""},{"en":"a high-pitched sound or voice is very high, and often unpleasant or annoying to listen to","cn":""},{"en":"a piercing sound or voice is very high and loud, often with the result that it is unpleasant or painful to listen to","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/tinny0205.mp3","us":"media/ldoce/hwd/ame/3/tinny.mp3"},"examples":[{"en":"The beer tasted tinny.","cn":"这啤酒喝起来有金属味。"},{"en":"tinny music","cn":"像金属片碰撞声的音乐"}],"oxford":{"phon":"ˈtɪni","pos":"adjective","senses":[{"en":"having a high, thin sound like small pieces of metal hitting each other","cn":"（声音）尖细的，尖声尖气的，如金属片碰撞声般的"},{"en":"having a taste like metal","cn":"有金属味的","ex":{"en":"The beer tasted tinny.","cn":"这啤酒喝起来有金属味。"}},{"en":"a can of beer","cn":"一罐啤酒","pos":"noun"}]}},"tibetan":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who comes from Tibet","cn":""},{"en":"the language of Tibet","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/lpd_tibetan.mp3","us":"media/ldoce/hwd/ame/c/tibetan_n.mp3"}},"tile":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"瓷砖;墙砖;地砖","en":"Tiles are flat, square pieces of baked clay, carpet, cork, or other substance, which are fixed as a covering onto a floor or wall.","ex":{"en":"Amy's shoes squeaked on the tiles as she walked down the corridor","cn":"埃米走过走廊时，鞋子踩在地砖上嘎吱作响。"}},{"pos":"N-VAR 可变名词","cn":"瓦片","en":"Tiles are flat pieces of baked clay which are used for covering roofs.","ex":{"en":"...a fine building, with a neat little porch and ornamental tiles on the roof.","cn":"一幢精致的建筑，有齐整的小巧柱廊，屋顶上覆着装饰瓦"}},{"pos":"VERB 动词","cn":"铺瓦于;贴地砖于","en":"When someone tiles a surface such as a roof or floor, they cover it with tiles.","ex":{"en":"He wants to tile the bathroom","cn":"他想在浴室里铺瓷砖。"}},{"pos":"PHRASE 短语","cn":"纵情玩乐，花天酒地(到深夜)","en":"If someone has a night on the tiles or is out on the tiles, they go out in the evening, for example to a bar or a club, and do not return home until very late.","ex":{"en":"Charlotte was dressed for a night on the tiles","cn":"夏洛特为彻夜狂欢精心打扮了一番。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat square piece of baked clay or other material, used for covering walls, floors etc","cn":"瓷砖﹔墙砖﹔地砖"},{"en":"a thin curved piece of baked clay used for covering roofs","cn":"瓦﹐瓦片"},{"en":"out drinking, dancing etc for enjoyment until late at night","cn":"在外玩乐至深夜"}]},"collocations":{"phrases":["ADJ. broken, damaged, loose, missing | decorative, glazed, hand-painted, plain | ceramic, clay, cork, mosaic, quarry, stone, terracotta, vin","VERB + TILE cover sth with, fit, lay, put down I'm laying ceramic floor tiles in the kitchen."]},"media":{"img":["media/ldoce/img/tiles.jpg"],"uk":"media/ldoce/hwd/bre/d/tile_n0205.mp3","us":"media/ldoce/hwd/ame/1/tile1.mp3"},"examples":[{"en":"a tiled bathroom","cn":"铺瓷砖的浴室"},{"en":"ceramic floor tiles","cn":"陶瓷地砖"}],"oxford":{"phon":"taɪl","pos":"noun","senses":[{"en":"a flat, usually square, piece of baked clay, carpet or other material that is used in rows for covering walls and floors","cn":"（贴墙或铺地用的）瓷砖，地砖，小方地毯，片状材料","ex":{"en":"ceramic floor tiles","cn":"陶瓷地砖"}},{"en":"a piece of baked clay that is used in rows for covering roofs","cn":"（铺屋顶的）瓦，瓦片","ex":{"en":"We lost a few tiles in the storm.","cn":"我们在暴风雨中损失了几块瓷砖。"}},{"en":"any of the small flat pieces that are used in particular board games","cn":"（某些桌面游戏的）板块，棋子"},{"en":"to cover a surface with tiles","cn":"铺瓦；铺地砖；贴瓷砖","ex":{"en":"a tiled bathroom","cn":"贴瓷砖的浴室"},"pos":"verb"},{"en":"to arrange several windows on a computer screen so that they fill the screen but do not cover each other","cn":"平铺显示，并列显示，瓦片式显示（视窗）","lab":"computing","pos":"verb"}]}},"tint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(少许)色彩；色调","en":"A tint is a small amount of colour.","ex":{"en":"Its large leaves often show a delicate purple tint","cn":"它的大叶子往往带点紫色。"}},{"pos":"N-COUNT 可数名词","cn":"染发剂;染发","en":"If you put a tint on your hair, you dye it a slightly different colour.","ex":{"en":"You've had a tint on your hair","cn":"你已经染过头发了。"}},{"pos":"VERB 动词","cn":"将…轻微染色;使略有…颜色","en":"If something is tinted, it has a small amount of a particular colour or dye in it.","ex":{"en":"Eyebrows can be tinted with the same dye","cn":"眉毛可以染成同样的颜色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"red, blue, yellow etc","cn":""},{"en":"a particular type of a colour","cn":""},{"en":"a particular colour or shade of a colour","cn":""}]},"collocations":{"phrases":["ADJ. rich | blue, bluish, etc. | autumn The fabrics were mainly in rich autumn tints, reds and oranges.","PREP. ~ of The branches of the trees were barely showing their first tint of green."]},"media":{"uk":"media/ldoce/hwd/bre/5/tint_n0205.mp3","us":"media/ldoce/hwd/ame/e/tint1.mp3"},"examples":[{"en":"leaves with red and gold autumn tints","cn":"金秋时节略呈红黄色的树叶"},{"en":"the brownish tint of an old photo","cn":"旧照片的淡褐色"}],"oxford":{"phon":"tɪnt","pos":"noun","senses":[{"en":"a shade or small amount of a particular colour; a small amount of colour covering a surface","cn":"色调；淡色彩；（一层）淡色，浅色","ex":{"en":"leaves with red and gold autumn tints","cn":"金秋时节略呈红黄色的树叶"}},{"en":"an artificial colour used to change the colour of your hair; the act of colouring the hair with a tint","cn":"染发剂；染发","ex":{"en":"a blond tint","cn":"金黄色染发剂"}},{"en":"to add a small amount of colour to something","cn":"为…轻微染色；给…略微着色","g":"[usually passive]","ex":{"en":"She’s having her eyelashes tinted.","cn":"她正在涂睫毛膏。"},"pos":"verb"},{"en":"to change the colour of somebody’s hair with a tint","cn":"染（发）","ex":{"en":"Have you tinted your hair?","cn":"你染过头发吗？"},"pos":"verb"}]}},"tiara":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指上流社会妇女在正式场合佩戴的)冕状宝石头饰","en":"A tiara is a metal band shaped like half a circle and decorated with jewels which a woman of very high social rank wears on her head at formal social occasions; also used of similar ornaments that girls or women wear on their heads."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of jewellery like a small crown , that a woman sometimes wears on very formal or important occasions 〔","cn":"女子在正式场合佩戴的〕冕状宝石头饰"}]},"media":{"uk":"media/ldoce/hwd/bre/1/tiara0205.mp3","us":"media/ldoce/hwd/ame/c/tiara.mp3"},"examples":[{"en":"a diamond tiara","cn":"钻石冠饰"}],"oxford":{"phon":"tiˈɑːrə","pos":"noun","senses":[{"en":"a piece of jewellery like a small crown decorated with precious stones, worn by a woman, for example a princess, on formal occasions","cn":"冠状头饰（女子用，如公主在正式场合戴的镶有宝石的王冠式头饰）"}]}},"tigress":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"母虎","en":"A tigress is a female tiger ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a female tiger","cn":"母虎﹐雌老虎"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41tigress.mp3","us":"media/ldoce/hwd/ame/3/tigress.mp3"},"oxford":{"phon":"ˈtaɪɡrəs","pos":"noun","senses":[{"en":"a female tiger","cn":"雌老虎"}]}},"titanium":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"钛","en":"Titanium is a light strong white metal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong light silver-white metal that is used to make aircraft and spacecraft, and is often combined with other metals. It is a chemical element : symbol Ti","cn":"钛〔一种化学元素﹐符号为Ti〕"}]},"media":{"uk":"media/ldoce/hwd/bre/e/titanium0205.mp3","us":"media/ldoce/hwd/ame/d/titanium.mp3"},"oxford":{"phon":"tɪˈteɪniəm","pos":"noun","senses":[{"en":"a chemical element. Titanium is a silver-white metal used in making various strong, light materials.","cn":"钛"}]}},"tilde":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鼻音化符号，腭化符号(西班牙语标在字母 n上，葡萄牙语标在字母 o 和 a 上)","en":"A tilde is a symbol that is written over the letter 'n' in Spanish ñ and the letters 'o' õ and 'a' ã in Portuguese to indicate the way in which they should be pronounced."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark (∼) placed over the letter ‘n’ in Spanish to show that it is pronounced /nj/ 〔","cn":"西班牙语中置于字母n之上的〕腭化符号"}]},"vocab":{"pos":"n","senses":[{"en":"A tilde is a character on a keyboard that looks like a wavy line (~). The Spanish alphabet has 27 letters instead of the English 26, because it includes both n and ñ, each of which is pronounced differently."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41tilde.mp3","us":"media/ldoce/hwd/ame/4/tilde.mp3"},"oxford":{"phon":"ˈtɪldə","pos":"noun","senses":[{"en":"the mark ( ˜ ) placed over letters in some languages and some vowels in the International Phonetic Alphabet to show how they should be pronounced, as in España, São Paulo and /pɒ̃ʃɒ̃/ (penchant)","cn":"腭化符号( ˜ )（置于某些语言的字母和国际音标中某些元音符号之上，表示发音方法）"},{"en":"the mark ( ˜ ), used in some dictionaries to represent the headword of an entry","cn":"波浪号，代字号（在本词典词条的某些地方用以代表首词）"}]}},"tip-top":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"头等的;第一流的;呱呱叫的","en":"You can use tip-top to indicate that something is extremely good.","ex":{"en":"Her hair was thick, glossy and in tip-top condition.","cn":"她的头发浓密亮泽，发质好得没话说。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"excellent","cn":"极好的﹐很棒的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41tip-top.mp3","us":"media/ldoce/hwd/ame/7/tip-top.mp3"},"examples":[{"en":"The house is in tip-top condition.","cn":"这座房子的状况没得挑。"},{"en":"The car’s in tip-top condition .","cn":"这辆车的车况非常好。"}],"oxford":{"phon":"ˌtɪp ˈtɒp","pos":"adjective","senses":[{"en":"excellent","cn":"极好的；头等的；一流的","ex":{"en":"The house is in tip-top condition.","cn":"这座房子的状况没得挑。"}}]}},"titanic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"庞大的;强大的","en":"If you describe something as titanic, you mean that it is very big or important, and usually that it involves very powerful forces.","ex":{"en":"The world had witnessed a titanic struggle between two visions of the future.","cn":"世界见证了两种对未来的构想之间的激烈较量。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very big, strong, impressive etc","cn":"巨大的﹔力大无比的﹔重大的"}]},"vocab":{"pos":"adj","senses":[{"en":"If two rival football teams played a close game that went into overtime, it could be could be said that winning it was a titanic struggle. This means it took a large amount of force and power to do so."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41titanic.mp3","us":"media/ldoce/hwd/ame/4/titanic1.mp3"},"examples":[{"en":"a titanic struggle between good and evil","cn":"善与恶之间的一场大搏斗"},{"en":"a titanic struggle","cn":"大搏斗"}],"oxford":{"phon":"taɪˈtænɪk","pos":"adjective","senses":[{"en":"very large, important, strong or difficult","cn":"巨大的；极重要的；强大的；极艰巨的","ex":{"en":"a titanic struggle between good and evil","cn":"善与恶之间的一场大搏斗"}}]}},"tizzy":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"(尤指因小事)激动，烦乱，紧张","en":"If you get in a tizzy or into a tizzy, you get excited, worried, or nervous about something, especially something that is not important.","ex":{"en":"He was in a right tizzy, muttering and swearing","cn":"他心情非常烦乱，嘴里咕咕哝哝地咒骂着。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"feeling worried, nervous, and confused","cn":"焦虑不安的﹐心慌意乱的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41tizzy.mp3","us":"media/ldoce/hwd/ame/9/tizzy.mp3"},"examples":[{"en":"She was in a real tizzy before the meeting.","cn":"她在会前感到心慌意乱。"}],"oxford":{"phon":"ˈtɪzi","pos":"noun","senses":[{"en":"a state of nervous excitement or worry","cn":"紧张；慌张；忧虑不安","ex":{"en":"She was in a real tizzy before the meeting.","cn":"她在会前感到心慌意乱。"}}]}},"tighten":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"抓紧;攥紧","en":"If you tighten your grip on something, or if your grip tightens, you hold the thing more firmly or securely.","ex":{"en":"Luke answered by tightening his grip on her shoulder","cn":"卢克的回应就是把她的肩头抓得更紧了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"绷紧，拉紧(绳、链)","en":"If you tighten a rope or chain, or if it tightens, it is stretched or pulled hard until it is straight.","ex":{"en":"The anchorman flung his whole weight back, tightening the rope","cn":"那个压阵队员使尽了全身力气往后拽，把绳子拉得紧紧的。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(对…)严加控制;(使)加强控制","en":"If a government or organization tightens its grip on a group of people or an activity, or if its grip tightens, it begins to have more control over it.","ex":{"en":"He knows he has considerable support for his plans to tighten his grip on the machinery of central government","cn":"他清楚有相当多的人支持他对中央政府机构加强控制的计划。"}},{"pos":"VERB 动词","cn":"拧紧，旋紧(螺钉、螺丝帽等)","en":"When you tighten a screw, nut, or other device, you turn it or move it so that it is more firmly in place or holds something more firmly.","ex":{"en":"I used my thumbnail to tighten the screw on my lamp","cn":"我用拇指指甲把台灯上的螺钉拧紧了。"}},{"pos":"VERB 动词","cn":"(身体局部)变僵硬，产生憋闷感，产生阻塞感","en":"If a part of your body tightens, the muscles in it become tense and stiff, for example because you are angry or afraid.","ex":{"en":"Sofia's throat had tightened and she couldn't speak","cn":"索菲娅喉咙哽住了，说不出话来。"}},{"pos":"VERB 动词","cn":"使(规定、政策、制度)更加严格；使更加有效","en":"If someone in authority tightens a rule, a policy, or a system, they make it stricter or more efficient.","ex":{"en":"The United States plans to tighten the economic sanctions currently in place","cn":"美国计划加大现有经济制裁的力度。"}},{"pos":"","cn":"","en":"to tighten your belt→see: ; to tighten the screw→see: ;"},{"pos":"","cn":"","en":"相关词组：tighten up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to reduce the amount of money that you regularly spend","cn":""},{"en":"to spend less money by buying only the things that you really need, or by buying cheaper things","cn":""},{"en":"to spend as little money as possible, only buying things you really need, because you have very little money and want to save it to use in the future","cn":""}]},"collocations":{"phrases":["ADV. fractionally, a little, slightly | convulsively, involuntarily Her fingers tightened convulsively with every jolt she received. | painf","VERB + TIGHTEN seem to | feel sth, sense sth He felt his stomach tighten. | make sth His words made her throat tighten.","PREP. about/around/round His hand tightened painfully around her wrist. | on Her grip seemed to tighten on the door handle. | in He saw his ","ADV. considerably","VERB + TIGHTEN take steps to Steps were taken to tighten discipline in the school.","PREP. up The law in this area has been tightened up considerably."]},"media":{"uk":"media/ldoce/hwd/bre/f/tighten0205.mp3","us":"media/ldoce/hwd/ame/c/tighten.mp3"},"examples":[{"en":"The police are tightening up on under-age drinking.","cn":"警方正在采取更加严厉的措施对付未成年人饮酒的问题。"},{"en":"Laws on gambling have tightened up recently.","cn":"有关赌博的法律最近变得更加严厉。"}],"oxford":{"phon":"ˈtaɪtn","pos":"verb","senses":[{"en":"to hold or fix something more securely in position; to make something or become more difficult to move, open or separate","cn":"使更加严格；加强","g":"[transitive, intransitive]","ex":{"en":"to tighten a lid/screw/rope/knot","cn":"拧紧盖子／螺钉；绷紧绳子；打紧结"}},{"en":"to make something become stricter","cn":"使更加严格；加强","g":"[transitive]","ex":{"en":"to tighten security","cn":"加强安全措施"}},{"en":"to become stretched so that it cannot stretch much further; to stretch or pull something in this way","cn":"使更加严格；加强","g":"[intransitive, transitive]","ex":{"en":"The rope holding the boat suddenly tightened and broke.","cn":"系船的绳子突然绷断了。"}},{"en":"to become painful or uncomfortable because of illness or emotion","cn":"（使）变紧，更加牢固","g":"[intransitive]","ex":{"en":"He felt his stomach tighten.","cn":"他感到肚子发紧。"}}]}},"tincture":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"酊剂","en":"A tincture is a medicine consisting of alcohol and a small amount of a drug.","ex":{"en":"...a few drops of tincture of iodine.","cn":"几滴碘酊"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical substance mixed with alcohol","cn":"酊剂"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A tincture is a trace or indication that reveals the presence of something. In pharmacology, a tincture is type of medicine extracted from a plant in an alcohol solution."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41tincture.mp3","us":"media/ldoce/hwd/ame/1/tincture.mp3"},"oxford":{"phon":"ˈtɪŋktʃə(r)","pos":"noun","senses":[{"en":"a substance dissolved in alcohol for use as a medicine","cn":"酊剂","ex":{"en":"a tincture of morphine","cn":"吗啡酊剂"}}]}},"tinpot":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地位低下的;无足轻重的","en":"You can use tinpot to describe a leader, country, or government that you consider to be unimportant and inferior to most others.","ex":{"en":"...a tinpot dictator.","cn":"无足轻重的独裁者"}}]},"examples":[{"en":"a tinpot dictator","cn":"领导无方的独裁者"}],"oxford":{"phon":"ˈtɪnpɒt","pos":"adjective","senses":[{"en":"not important and of little worth or use","cn":"无足轻重的；不起作用的","ex":{"en":"It's worrying that soon any tinpot dictator will be able to get their hands on nuclear weapons.","cn":"令人担忧的是，很快任何一个无能的独裁者都将能够获得核武器。"}}]}},"tie-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(交通)阻塞","en":"A tie-up or a traffic tie-up is a long line of vehicles that cannot move forward because there is too much traffic, or because the road is blocked by something.","ex":{"en":"In some cities this morning, there were traffic tie-ups up to 40 miles long.","cn":"今天早上，在有些城市汽车排起了长达 40 英里的长龙。"}},{"pos":"N-COUNT 可数名词","cn":"经济关系;贸易往来","en":"A tie-up between two organizations is a business connection that has been arranged between them.","ex":{"en":"The deal is expected to result in similar tie-ups between big media companies and telecommunications operators.","cn":"这笔交易可能促成大型传媒公司和电信运营商结成类似的联营关系。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an agreement to become business partners 〔","cn":"公司的〕联营﹐联合"},{"en":"a strong connection between two or more things","cn":"关系﹐联系"},{"en":"a situation in which traffic is prevented from moving or there is a problem which prevents a system or plan from working 〔","cn":"交通的〕阻塞﹔〔系统或计划的〕停顿﹐停滞不前"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41tie-up.mp3","us":"media/ldoce/hwd/ame/1/tie-up.mp3"},"examples":[{"en":"They're negotiating a tie-up with Ford.","cn":"他们正在与福特公司洽谈合作事宜。"},{"en":"a tie-up between politics and economics","cn":"政治和经济之间的关系"}],"oxford":{"phon":"ˈtaɪ ʌp","pos":"noun","senses":[{"en":"an agreement between two companies to join together","cn":"（两家公司的）联合，合作","lab":"British English","ex":{"en":"They're negotiating a tie-up with Ford.","cn":"他们正在与福特公司洽谈合作事宜。"}},{"en":"a connection between two or more things","cn":"联系；关系；关联","lab":"British English","ex":{"en":"a tie-up between politics and economics","cn":"政治和经济之间的关系"}},{"en":"a situation in which something stops working or moving forward","cn":"停顿；停滞不前","lab":"especially North American English","ex":{"en":"a traffic tie-up","cn":"交通阻塞"}}]}},"tipster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(专门提供赛马内幕消息的)情报贩子","en":"A tipster is someone who tells you, usually in exchange for money, which horses they think will win particular races, so that you can bet money on the horses."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who gives information about which horse is likely to win a race 〔","cn":"提供赛马信息的〕情报贩子"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41tipster.mp3","us":"media/ldoce/hwd/ame/c/tipster.mp3"},"oxford":{"phon":"ˈtɪpstə(r)","pos":"noun","senses":[{"en":"a person who tells you, often in exchange for money, which horse is likely to win a race, so that you can bet on it and win money","cn":"提供赛马情报的人（常指贩卖情报者）"},{"en":"a person who gives information to the police about a crime or criminal","cn":"（犯罪行为等的）举报者，告密者","lab":"especially North American English"}]}},"tiling":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"瓦屋顶;地砖面;瓷砖面","en":"You can refer to a surface that is covered by tiles as tiling .","ex":{"en":"The kitchen has smart black tiling, worksurfaces and cupboards.","cn":"厨房有漂亮的黑色瓷砖地面、操作台面和碗橱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area or surface covered with tiles, or the work of covering a surface with tiles","cn":"瓷砖[地砖]面﹐瓦屋顶﹔盖瓦﹐贴瓷砖﹐铺地砖"}]},"media":{"uk":"media/ldoce/hwd/bre/a/tiling0205.mp3","us":"media/ldoce/hwd/ame/6/laadtiling.mp3"},"oxford":{"phon":"ˈtaɪlɪŋ","pos":"noun","senses":[{"en":"an area covered with tiles","cn":"瓷砖面；地砖面；瓦屋顶"},{"en":"the work of covering a floor, wall, etc. with tiles","cn":"盖瓦；贴瓷砖；铺地砖"}]}},"tinfoil":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(包裹食物用的)锡箔，锡纸","en":"Tinfoil consists of shiny metal in the form of a thin sheet which is used for wrapping food."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"thin shiny metal that bends like paper and is used for covering food 〔","cn":"用于包裹食物等的〕锡箔﹐锡纸"}]},"media":{"uk":"media/ldoce/hwd/bre/1/tinfoil0205.mp3","us":"media/ldoce/hwd/ame/c/tinfoil.mp3"},"oxford":{"phon":"ˈtɪnfɔɪl","pos":"noun","senses":[{"en":"metal made into very thin sheets that is used for covering or wrapping things, especially food","cn":"（尤指包装食物等用的）箔","ex":{"en":"Cover with tinfoil and bake for 20 minutes.","cn":"盖上锡纸，烤20分钟。"}}]}},"tibia":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胫骨","en":"Your tibia is the inner bone of the two bones in the lower part of your leg."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bone in the front of your leg","cn":"胫骨"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41tibia.mp3","us":"media/ldoce/hwd/ame/c/tibia.mp3"},"oxford":{"phon":"ˈtɪbiə","pos":"noun","senses":[{"en":"the shin bone","cn":"胫骨"}]}},"tinker":{"collins":{"senses":[{"pos":"VERB 动词","cn":"小修;小补;摆弄","en":"If you tinker with something, you make some small changes to it, in an attempt to improve it or repair it.","ex":{"en":"Instead of the Government admitting its error, it just tinkered with the problem","cn":"政府没有承认错误，只是敷衍了事地处理问题。"}},{"pos":"N-COUNT 可数名词","cn":"(旧时的)补锅匠，修理匠","en":"In former times, a tinker was a person who did not have a fixed home, but travelled from place to place mending metal pots and doing other small repair jobs."},{"pos":"N-COUNT 可数名词","cn":"(尤指爱尔兰裔的)流浪者，吉卜赛人","en":"Some people refer to any traveller or gipsy, especially one who is Irish, as a tinker ."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make small changes to something in order to repair it or make it work better","cn":"做小改动﹐做小修补﹔摆弄"},{"en":"in the past, a tinker was someone who travelled from place to place selling things or repairing metal pots, pans etc 〔","cn":"旧时走街串巷的〕小贩﹐补锅匠"},{"en":"a disobedient or annoying young child","cn":"顽童﹐小淘气"}]},"media":{"uk":"media/ldoce/hwd/bre/c/tinker_v0205.mp3","us":"media/ldoce/hwd/ame/9/tinker1.mp3"},"examples":[{"en":"Congress has been tinkering with the legislation.","cn":"国会一直在对这项立法做些小修小补。"},{"en":"Dad was always tinkering around with engines.","cn":"爸爸总是在摆弄发动机。"}],"oxford":{"phon":"ˈtɪŋkə(r)","pos":"noun","senses":[{"en":"(in the past) a person who travelled from place to place, selling or repairing things","cn":"（旧时走街串巷的）小炉匠，补锅匠，白铁匠"},{"en":"an offensive word for a Traveller, Romani or other member of the travelling community","cn":"吉卜赛人；流浪者","lab":"British English, offensive，，"},{"en":"to make small changes to something in order to repair or improve it, especially in a way that may not be helpful","cn":"（尤指可能不起作用地）小修补，小修理","ex":{"en":"He’s in the garage tinkering with his bike.","cn":"他在车库里摆弄他的自行车。"},"pos":"verb"}]}},"tightrope":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(马戏团的表演用)绷索，钢丝","en":"A tightrope is a tightly stretched piece of rope on which someone balances and performs tricks in a circus."},{"pos":"N-COUNT 可数名词","cn":"走钢丝(比喻处境艰难，必须小心行事)","en":"You can use tightrope in expressions such as walk a tightrope and live on a tightrope to indicate that someone is in a difficult situation and has to be very careful about what they say or do.","ex":{"en":"School administrators walk a tightrope between the demands of the community and the realities of how children really behave","cn":"学校管理者在社区的要求和孩子们的实际表现之间小心翼翼地平衡局面。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a rope or wire high above the ground that someone walks along in a circus 〔","cn":"马戏团表演用的〕钢丝﹐绷索"},{"en":"to be in a difficult situation in which something bad could happen if you make a mistake","cn":"走钢丝〔比喻处境困难﹐如有差错就会发生不好的事〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/tightrope0205.mp3","us":"media/ldoce/hwd/ame/d/tightrope.mp3"},"examples":[{"en":"a tightrope walker","cn":"走钢丝演员"},{"en":"I feel as though I’m walking a tightrope between success and failure.","cn":"我感到自己就像走钢丝一样﹐在成功与失败之间摇摆。"}],"oxford":{"phon":"ˈtaɪtrəʊp","pos":"noun","senses":[{"en":"a rope or wire that is stretched tightly high above the ground and that performers walk along, especially in a circus","cn":"（尤指马戏团表演用的）绷紧的绳索，绷紧的钢丝","ex":{"en":"a tightrope walker","cn":"走钢丝演员"}}]}},"titter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指窘迫时)干笑，傻笑，窃笑，哧哧地笑","en":"If someone titters, they give a short nervous laugh, especially when they are embarrassed about something.","ex":{"en":"Mention sex therapy and most people will titter in embarrassment.","cn":"提及性治疗，大多数人会尴尬地偷笑。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make sounds with your voice and move your face, because you think that something is funny","cn":""},{"en":"to laugh quickly in a high voice, especially in a slightly silly way, or because you are nervous or embarrassed","cn":""},{"en":"to laugh quietly, especially because you are thinking about or reading something funny","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A titter is an awkward laugh at something that you shouldn’t be laughing at, like during dinner when Uncle Marvin makes a joke about your mother’s new hairstyle. If you try to hide your laugh, it’s probably a titter ."}]},"media":{"uk":"media/ldoce/hwd/bre/d/titter0205.mp3","us":"media/ldoce/hwd/ame/1/titter.mp3"},"examples":[{"en":"At the word ‘breast’, some of the class tittered.","cn":"听到“乳房”这个词﹐班上有些同学嗤嗤地笑了起来。"}],"oxford":{"phon":"ˈtɪtə(r)","pos":"noun","senses":[{"en":"a quiet laugh, especially a nervous or embarrassed one","cn":"（尤指紧张或尴尬地）傻笑，嗤嗤地笑；窃笑","ex":{"en":"His comments raised a titter.","cn":"他的评论引起了一阵窃笑。"}},{"en":"to laugh quietly, especially in a nervous or embarrassed way","cn":"（尤指紧张或尴尬地）傻笑，嗤嗤地笑；窃笑","ex":{"en":"There was an embarrassing pause on stage and the audience began to titter.","cn":"舞台上出现了令人尴尬的冷场，于是观众开始窃笑起来。"},"pos":"verb"}]}},"timeworn":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"久经使用的;陈旧的;古旧的","en":"Something that is time-worn is old or has been used a lot over a long period of time.","ex":{"en":"Even in the dim light the equipment looked old and time-worn","cn":"即便在昏暗的光线下，那台设备也显得陈旧不堪。"}}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective timeworn is good for describing something that's been said or done so often that it's not interesting or fresh any more. A movie with a timeworn plot has few surprises."}]}},"time-honoured":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"古老的;由来已久的;历史悠久的","en":"A time-honoured tradition or way of doing something is one that has been used and respected for a very long time.","ex":{"en":"The beer is brewed in the time-honoured way at the Castle Eden Brewery.","cn":"伊登堡酿酒厂以传统酿制方式酿造啤酒。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a time-honoured method or custom is one that has existed for a long time 〔","cn":"方法﹑习俗等〕古老的﹐历史悠久的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/time_honoured0205.mp3","us":"media/ldoce/hwd/ame/2/time-honored.mp3"},"examples":[{"en":"They showed their approval in the time-honoured way (= by clapping, for example).","cn":"他们以传统的方式表示同意。"},{"en":"Sharon became involved with music in the time-honoured fashion – through her family.","cn":"莎伦是通过家庭熏陶这一传统方式走上音乐道路的。"}],"oxford":{"phon":"ˈtaɪm ɒnəd","pos":"adjective","senses":[{"en":"respected because it has been used or done for a long time","cn":"古老而受到尊重的；历史悠久的；由来已久的","ex":{"en":"They showed their approval in the time-honoured way (= by clapping, for example).","cn":"他们以传统的方式表示同意。"}}]}},"tier":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一排;一行;一列","en":"A tier is a row or layer of something that has other layers above or below it.","ex":{"en":"...the auditorium with the tiers of seats around and above it.","cn":"四周和上方有一排排座位的礼堂"}},{"pos":"N-COUNT 可数名词","cn":"(组织或系统的)层，级","en":"A tier is a level in an organization or system.","ex":{"en":"Islanders have campaigned for the abolition of one of the three tiers of municipal power on the island.","cn":"岛上居民发起一场运动，要求废除岛上三级市政管理层中的一级。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"several things that are standing next to each other or one behind the other","cn":""},{"en":"a line of things that have been deliberately put next to each other, especially one of several lines that are arranged one behind the other","cn":""},{"en":"a line of computers, televisions, or other electrical equipment","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"A tier is a level or a layer. If you sit in the top tier of seats at a concert, you can see the whole stage and most of the audience — but you probably have to climb lots of stairs."}]},"media":{"uk":"media/ldoce/hwd/bre/9/tier0205.mp3","us":"media/ldoce/hwd/ame/7/tear1.mp3"},"examples":[{"en":"We have introduced an extra tier of administration.","cn":"我们额外增加了一层管理。"},{"en":"The seating is arranged in tiers.","cn":"座位是一级级排列的。"}],"oxford":{"phon":"tɪə(r)","pos":"noun","senses":[{"en":"a row or layer of something that has several rows or layers placed one above the other","cn":"级；阶；层","ex":{"en":"a wedding cake with three tiers","cn":"三层的结婚蛋糕"}},{"en":"one of several levels in an organization or a system","cn":"阶层；等级","ex":{"en":"We have introduced an extra tier of administration.","cn":"我们额外增加了一层管理。"}}]}},"tittle-tattle":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"闲聊;胡侃;流言蜚语","en":"If you refer to something that a group of people talk about as tittle-tattle, you mean that you disapprove of it because it is not important, and there is no real evidence that it is true.","ex":{"en":"...tittle-tattle about the private lives of minor celebrities.","cn":"有关二三流名人隐私生活的闲言碎语"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"unimportant conversation about other people and what they are doing 〔","cn":"关于别人的〕闲聊﹔闲言碎语"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41tittle-tattle.mp3","us":"media/ldoce/hwd/ame/e/tittle-tattle.mp3"},"oxford":{"phon":"ˈtɪtl tætl","pos":"noun","senses":[{"en":"unimportant talk, usually not true, about other people and their lives","cn":"闲聊；张家长李家短","ex":{"en":"The story was nothing more than idle tittle-tattle.","cn":"这个故事只不过是闲聊而已。"}}]}},"tidbit":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of food that tastes good","cn":"少量的美味佳肴[珍馐]"},{"en":"a small but interesting piece of information, news etc","cn":"花絮﹐趣闻"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41tidbit.mp3","us":"media/ldoce/hwd/ame/b/tidbit.mp3"},"examples":[{"en":"juicy tidbits of hot news","cn":"有趣的热门花边新闻"}],"oxford":{"phon":"ˈtɪdbɪt","pos":"noun","senses":[{"en":"a small special piece of food","cn":"小片食物"}]}},"tinned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"罐装的;听装的","en":"Tinned food is food that has been preserved by being sealed in a tin.","ex":{"en":"...tinned tomatoes.","cn":"罐头番茄"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"tinned food is food that is sold in small metal containers which can be kept for a long time before they are opened 〔","cn":"食品〕罐装的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdetinned.mp3","us":"media/ldoce/hwd/ame/3/laadtinned.mp3"},"examples":[{"en":"tinned fruit","cn":"罐头水果"},{"en":"tinned tomatoes","cn":"罐头番茄"}],"oxford":{"phon":"tɪnd","pos":"adjective","senses":[{"en":"preserved in a can","cn":"罐装的","ex":{"en":"tinned fruit","cn":"罐头水果"}}]}},"tiff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(亲密朋友、情侣之间的)小争吵，口角，拌嘴","en":"A tiff is a small unimportant quarrel, especially between two close friends or between people in a romantic relationship."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an argument about something that is not important","cn":""},{"en":"an argument that is not very serious, between people who are in love","cn":""},{"en":"a slight argument – a rather formal word which is often used humorously","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/tiff0205.mp3","us":"media/ldoce/hwd/ame/5/tiff.mp3"},"examples":[{"en":"to have a tiff with sb","cn":"与某人口角"},{"en":"Dave’s had a tiff with his girlfriend.","cn":"戴夫同女友吵嘴了。"}],"oxford":{"phon":"tɪf","pos":"noun","senses":[{"en":"a slight argument between close friends or two people who love each other","cn":"（朋友或情人之间的）争执，拌嘴，口角，吵嘴","ex":{"en":"to have a tiff with somebody","cn":"与某人口角"}},{"en":"a form in which images can be stored and shown on a computer; an image created in this form (the abbreviation for ‘tagged image file format’)","cn":"标签式图像文件格式，TIFF 格式，TIFF 图像（全写为 tagged image file format）"}]}},"tilt":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)倾斜;(使)歪斜","en":"If you tilt an object or if it tilts, it moves into a sloping position with one end or side higher than the other.","ex":{"en":"She tilted the mirror and began to comb her hair","cn":"她斜过镜子开始梳理头发。"}},{"pos":"VERB 动词","cn":"(略微)倾侧(身体部位)，仰(头)，把(头)歪向一边","en":"If you tilt part of your body, usually your head, you move it slightly upwards or to one side.","ex":{"en":"Mari tilted her head back so that she could look at him","cn":"玛丽把头向后仰，以便能看到他。"}},{"pos":"N-COUNT 可数名词","cn":"倾斜;倾侧;倾斜度","en":"The tilt of something is the fact that it tilts or slopes, or the angle at which it tilts or slopes.","ex":{"en":"...calculations based on our understanding of the tilt of the earth's axis","cn":"基于我们对地轴倾斜度的了解的计算"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)倾向于;(使)偏向于","en":"If a person or thing tilts towards a particular opinion or if something tilts them towards it, they change slightly so that they become more in agreement with that opinion or position.","ex":{"en":"When the political climate tilted towards fundamentalism he was threatened","cn":"当政治气候倾向于原教旨主义时，他受到了威胁。"}},{"pos":"N-SING 单数名词","cn":"倾向;偏向","en":"If there is a tilt towards a particular opinion or position, that opinion or position is favoured or begins to be favoured.","ex":{"en":"The chairman also criticised the plan for its tilt towards higher taxes rather than lower spending.","cn":"主席也批评该计划倾向于主张高税收而不是低消费。"}},{"pos":"N-COUNT 可数名词","cn":"尝试;努力","en":"A tilt at something is an attempt to win or obtain it.","ex":{"en":"His first tilt at Parliament came in the same year but he failed to win the seat","cn":"同年，他首次尝试进入国会，但没有赢得席位。"}},{"pos":"PHRASE 短语","cn":"全速地;全力地","en":"To move full tilt or at full tilt means to move with as much speed, energy, or force as possible.","ex":{"en":"As John approached at full tilt he saw a queue of traffic blocking the road","cn":"约翰全速接近的时候，看到一大串车辆挡住了道路。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move a part of your body, especially your head or chin, upwards or to the side （","cn":"使）〔头﹑下巴等〕倾斜﹐（使）倾侧"},{"en":"to move or make something move into a position where one side is higher than the other （","cn":"使）〔物体〕倾斜"},{"en":"if an opinion or situation tilts, or if something tilts it, it changes so that people start to prefer one person, belief, or action to others （","cn":"使）倾向于﹐（使）偏向于"}]},"vocab":{"pos":"1 v n 2 n v 3 n","senses":[{"en":"Tilt is both a noun and a verb. It has many shades of meaning, but most involve a slope or slant. When you're dizzy from eating too much, you might tilt when you walk away from the table."}]},"collocations":{"phrases":["ADV. sharply The ground tilted sharply downwards. | a little, slightly | back/backwards, down/downwards, forward, up/upwards","PREP. away from Tilt the mirror away from you. | towards Her face was tilted towards the sky.","PHRASES tilted to one side She thought for a minute, her head tilted to one side."]},"media":{"uk":"media/ldoce/hwd/bre/b/tilt_n0205.mp3","us":"media/ldoce/hwd/ame/6/tilt1.mp3"},"examples":[{"en":"The conditions may tilt the balance in favour of the Kenyan runners.","cn":"这些条件可能对肯尼亚赛跑运动员有利。"},{"en":"The seat tilts forward, when you press this lever.","cn":"按这个控制柄，座位就向前倾斜。"}],"oxford":{"phon":"tɪlt","pos":"verb","senses":[{"en":"to move, or make something move, into a position with one side or end higher than the other","cn":"（使）倾斜，倾侧","g":"[intransitive, transitive]","ex":{"en":"Suddenly the boat tilted to one side.","cn":"小船突然倾向一侧。"}},{"en":"to make something/somebody change slightly so that one particular opinion, person, etc. is preferred or more likely to succeed than another; to change in this way","cn":"使倾向于；使向…倾斜；偏向","g":"[transitive, intransitive]","ex":{"en":"The conditions may tilt the balance in favour of the Kenyan runners.","cn":"这些条件可能对肯尼亚赛跑运动员有利。"}},{"en":"a position in which one end or side of something is higher than the other; an act of tilting something to one side","cn":"倾斜；倾侧","g":"[countable, usually singular, uncountable]","ex":{"en":"The table is at a slight tilt.","cn":"这桌子有点儿倾斜。"},"pos":"noun"},{"en":"an attempt to win something or defeat somebody","cn":"（意欲赢得某物或战胜某人的）企图，尝试","g":"[countable]","lab":"British English","ex":{"en":"She aims to have a tilt at the world championship next year.","cn":"她的目标是明年问鼎世界冠军。"},"pos":"noun"}]}},"titular":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"名义上的;有名无实的;徒有虚名的","en":"A titular job or position has a name that makes it seem important, although the person who has it is not really important or powerful.","ex":{"en":"He is titular head, and merely signs laws occasionally.","cn":"他是名义上的首脑，不过偶尔签字批准法律法规。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is the official leader or ruler of a country but who does not have real power or authority","cn":"名义元首/领导/君主等"}]},"vocab":{"pos":"adj","senses":[{"en":"You might say you’re the boss man in your household, but if everybody else in the family ignores you, 'boss man' is probably a titular position for you. In other words, it’s just a title. There’s no power behind it."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41titular.mp3","us":"media/ldoce/hwd/ame/9/titular.mp3"},"examples":[{"en":"the titular head of state","cn":"名义上的国家元首"}],"oxford":{"phon":"ˈtɪtjələ(r)","pos":"adjective","senses":[{"en":"having a particular title or status but no real power or authority","cn":"名义上的；有名无实的；徒有虚名的","lab":"formal","ex":{"en":"the titular head of state","cn":"名义上的国家元首"}},{"en":"the titular character of a book, play, film, etc. is the one mentioned in the title","cn":"标题的；被用作标题的"}]}},"tiresome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讨厌的;烦人的;令人厌倦的","en":"If you describe someone or something as tiresome, you mean that you find them irritating or boring.","ex":{"en":"...the tiresome old lady next door","cn":"隔壁讨人嫌的老太太"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel annoyed or impatient","cn":"恼人的﹐令人厌烦的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/tiresome0205.mp3","us":"media/ldoce/hwd/ame/2/tiresome.mp3"},"examples":[{"en":"Buying a house can be a very tiresome business.","cn":"买房子有时是件很麻烦的事。"},{"en":"The children were being very tiresome.","cn":"这些孩子非常讨人嫌。"}],"oxford":{"phon":"ˈtaɪəsəm","pos":"adjective","senses":[{"en":"making you feel annoyed","cn":"讨厌的；令人厌烦的；烦人的","ex":{"en":"Buying a house can be a very tiresome business.","cn":"买房子有时是件很麻烦的事。"}}]}},"tights":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"紧身衣;紧身裤袜","en":"Tights are a piece of clothing, usually worn by women and girls. They are usually made of nylon and cover the hips, legs and feet.","ex":{"en":"...a new pair of tights.","cn":"新的紧身裤袜"}},{"pos":"N-PLURAL 复数名词","cn":"(通常指舞蹈演员、杂技演员或人们运动时穿的)紧身衣","en":"Tights are a piece of tight clothing, usually worn by dancers, acrobats, or people in exercise classes, and covering the hips and each leg."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of women’s clothing made of very thin material that fits tightly over the feet and legs and goes up to the waist","cn":"女用连裤袜"},{"en":"a piece of clothing similar to women’s tights but too thick to see through, worn especially by dancers 〔","cn":"尤指舞蹈员穿的〕紧身衣"}]},"collocations":{"phrases":["ADJ. opaque, thick | sheer | fishnet | 15-denier, etc. | support | laddered","QUANT. pair","VERB + TIGHTS pull on | peel off | ladder","TIGHTS + VERB ladder","PHRASES a ladder in your tights •"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdetights.mp3","us":"media/ldoce/hwd/ame/9/tights.mp3"},"examples":[{"en":"a pair of tights","cn":"一条连裤袜"}],"oxford":{"phon":"taɪts","pos":"noun","senses":[{"en":"a piece of clothing made of very thin cloth that fits closely over the hips, legs and feet, usually worn under other clothes","cn":"（女用）连裤袜，紧身裤","lab":"British English","ex":{"en":"a pair of tights","cn":"一条连裤袜"}},{"en":"a piece of clothing similar to tights but made of thicker cloth, worn especially by dancers","cn":"（尤指舞蹈演员穿的）紧身衣裤"}]}},"titbit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"趣闻;花絮","en":"You can refer to a small piece of information about someone's private affairs as a titbit, especially when it is interesting and shocking.","ex":{"en":"...titbits of gossip gleaned from the corridors of power","cn":"从权力中心收集来的趣闻轶事"}},{"pos":"N-COUNT 可数名词","cn":"少量食物","en":"A titbit is a small piece of food.","ex":{"en":"She offered Molly tidbits: a chicken drumstick, some cheese.","cn":"她给了莫莉一些吃的：一根鸡腿下段和一些奶酪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of food","cn":"少量的食物"},{"en":"a small but interesting piece of information etc","cn":"趣闻/八卦/花边新闻等"}]},"media":{"uk":"media/ldoce/hwd/bre/1/titbit0205.mp3","us":"media/ldoce/hwd/ame/f/ld41titbit.mp3"},"examples":[{"en":"She had saved a few titbits for her cat.","cn":"她给猫留了点好吃的东西。"},{"en":"titbits of gossip","cn":"蜚短流长"}],"oxford":{"phon":"ˈtɪtbɪt","pos":"noun","senses":[{"en":"a small special piece of food","cn":"小片食物","ex":{"en":"She had saved a few titbits for her cat.","cn":"她给猫留了点好吃的东西。"}},{"en":"a small but interesting piece of news","cn":"花絮；趣闻；逸事","ex":{"en":"titbits of gossip","cn":"蜚短流长"}}]}},"timbered":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"木制的;木结构的","en":"A timbered building has a wooden frame or wooden beams showing on the outside.","ex":{"en":"Timbered cottages stood around a triangular green.","cn":"几所乡村小木屋环绕在三角形绿地周围。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"timbered buildings have a frame made of wooden beams, or have wooden beams showing on the outside","cn":"木制的﹔木结构的"},{"en":"timbered houses/cottages","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41timbered.mp3","us":"media/ldoce/hwd/ame/1/ld41timbered.mp3"},"oxford":{"phon":"ˈtɪmbəd","pos":"adjective","senses":[{"en":"built of timbers; with a framework of timbers","cn":"木制的；木结构的","ex":{"en":"a timbered cottage","cn":"一座木屋"}}]}},"tinkle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"叮当作响;发出叮当声","en":"If something tinkles, it makes a clear, high-pitched, ringing noise, especially as small parts of it strike a surface.","ex":{"en":"A fresh cascade of splintered glass tinkled to the floor","cn":"大量刚裂开的玻璃碎片叮叮当当地落到地板上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(钟、铃)作响;敲响(钟、铃)","en":"If a bell tinkles or if you tinkle it, it makes a quiet ringing noise as you shake it.","ex":{"en":"An old-fashioned bell tinkled as he pushed open the door","cn":"当他推开门时，一口旧式的钟丁零零地响了起来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a loud sound caused especially when something hard or heavy hits something else","cn":""},{"en":"a very loud sound caused when something hits something else, especially when damage is caused","cn":""},{"en":"a quiet low sound made when a heavy object falls down onto surface","cn":""}]},"collocations":{"phrases":["ADJ. faint, little, soft","VERB + TINKLE hear","PREP. with a ~ The wine glass dropped to the floor with a tinkle."]},"media":{"uk":"media/ldoce/hwd/bre/5/tinkle_n0205.mp3","us":"media/ldoce/hwd/ame/d/tinkle1.mp3"},"examples":[{"en":"A bell tinkled as the door opened.","cn":"房门一开，铃声丁零响了。"},{"en":"the tinkle of glass breaking","cn":"玻璃破碎发出的当啷声"}],"oxford":{"phon":"ˈtɪŋkl","pos":"noun","senses":[{"en":"a light, high ringing sound","cn":"丁零声；当啷响","g":"[singular, uncountable]","ex":{"en":"the tinkle of glass breaking","cn":"玻璃破碎发出的当啷声"}},{"en":"a phone call","cn":"电话通话","lab":"British English, old-fashioned, informal，，，，"},{"en":"an act of urinating","cn":"撒尿","lab":"informal","ex":{"en":"to have a tinkle","cn":"撒尿"}},{"en":"to make a series of light, high ringing sounds; to make something produce this sound","cn":"（使）发出叮当声，丁零响","ex":{"en":"A bell tinkled as the door opened.","cn":"房门一开，铃声丁零响了。"},"pos":"verb"}]}},"tit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山雀","en":"A tit is a small European bird that eats insects and seeds. There are several kinds of tit."},{"pos":"N-COUNT 可数名词","cn":"(女性的)乳头，奶子","en":"A woman's tits are her breasts."},{"pos":"N-COUNT 可数名词","cn":"笨蛋;傻瓜","en":"If you call someone a tit, you are insulting them and saying that they are stupid."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman’s breast 〔","cn":"妇女的〕乳房﹐奶子"},{"en":"to annoy someone a lot","cn":"烦扰某人﹐使某人厌烦"},{"en":"a type of small European bird","cn":"山雀〔欧洲的一种小型鸟〕"}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdetit.mp3","us":"media/ldoce/hwd/ame/c/tit1.mp3"},"examples":[{"en":"a great tit","cn":"大山雀"}],"oxford":{"phon":"tɪt","pos":"noun","senses":[{"en":"a woman’s breast or nipple","cn":"（女人的）奶子，奶头，乳头","g":"[usually plural]","lab":"taboo, slang，，"},{"en":"an offensive word for a person you think is stupid","cn":"蠢货；笨蛋","lab":"British English, offensive, slang，，，，"},{"en":"a small European bird. There are several types of tit.","cn":"山雀","ex":{"en":"a great tit","cn":"大山雀"}}]}},"tiptop":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"头等的;第一流的;呱呱叫的","en":"You can use tip-top to indicate that something is extremely good.","ex":{"en":"Her hair was thick, glossy and in tip-top condition.","cn":"她的头发浓密亮泽，发质好得没话说。"}}]}},"timeserver":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"混日子的人;工作马虎的人;得过且过的人","en":"If you refer to someone as a time-server, you disapprove of them because they are making very little effort at work and are just waiting until they retire or leave for a new job."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does the least amount of work possible in their job","cn":"磨洋工的人﹐混时间的人"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41timeserver.mp3","us":"media/ldoce/hwd/ame/e/timeserver.mp3"}},"tinge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"微量，少许，一丝，几分(颜色、感情或性质)","en":"A tinge of a colour, feeling, or quality is a small amount of it.","ex":{"en":"His skin had an unhealthy greyish tinge","cn":"他的皮肤有种不健康的淡灰色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small amount of a colour, emotion, or quality","cn":"淡淡的色调﹔些许﹐一点﹐一丝〔颜色﹑情绪或品质〕"},{"en":"to give something a small amount of a particular colour, emotion, or quality","cn":"着淡色于…﹔使带有一点〔情绪﹑特质等〕"}]},"vocab":{"pos":"v n","senses":[{"en":"A tinge is a slight amount of something, especially a faint color. If you wear SPF30 to the beach, you'll only come home with a tinge of tan."}]},"collocations":{"phrases":["ADJ. faint, slight blue with a slight tinge of purple | blue, bluish, etc. a slight reddish tinge","VERB + TINGE have","PREP. ~ of a tinge of regret | ~ to The sky had a slight pink tinge to it."]},"media":{"uk":"media/ldoce/hwd/bre/6/tinge_v0205.mp3","us":"media/ldoce/hwd/ame/5/tinge1.mp3"},"examples":[{"en":"There was a faint pink tinge to the sky.","cn":"天空略带一点淡淡的粉红色。"},{"en":"a look of surprise tinged with disapproval","cn":"带有几分不满的惊奇神情"}],"oxford":{"phon":"tɪndʒ","pos":"verb","senses":[{"en":"to add a small amount of colour to something","cn":"为…轻微染色；给…略微着色","ex":{"en":"white petals tinged with blue","cn":"略带蓝色的白花瓣"}},{"en":"to add a small amount of a particular emotion or quality to something","cn":"使略带…感情（或性质）","ex":{"en":"a look of surprise tinged with disapproval","cn":"带有几分不满的惊奇神情"}},{"en":"a small amount of a colour, feeling or quality","cn":"微量，少许，一丝，几分（颜色、感情或性质）","ex":{"en":"to feel a tinge of envy","cn":"感到几分妒忌"},"pos":"noun"}]}},"tie-dye":{"collins":{"senses":[{"pos":"VERB 动词","cn":"扎染(指将布料打结后用染料染色)","en":"If a piece of cloth or a garment is tie-dyed, it is tied in knots and then put into dye, so that some parts become more deeply coloured than others.","ex":{"en":"He wore a T-shirt that had been tie-dyed in bright colours","cn":"他身穿一件颜色鲜艳的扎染的 T 恤。"}},{"pos":"N-VAR 可变名词","cn":"扎染衣服;扎染布料","en":"A tie-dye is a garment or piece of cloth that has been tie-dyed.","ex":{"en":"They wore tie-dyes and ponchos.","cn":"他们身穿扎染衣服和披风。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a pattern on a piece of material by tying string around it and colouring it with dye (= coloured liquid )","cn":"扎染〔把布料捆扎后再用染料染色〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41tie-dye.mp3","us":"media/ldoce/hwd/ame/7/tie-dye.mp3"},"oxford":{"phon":"ˈtaɪ daɪ","pos":"verb","senses":[{"en":"to make patterns on cloth by tying knots in it or tying string around it before you put it in a dye, so that some parts receive more colour than others","cn":"扎染（织物）"}]}},"tinderbox":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"危机四伏的形势","en":"If you say that a situation is a tinderbox, you mean that it is very tense and something dangerous or unpleasant is likely to happen very soon."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place or situation that is dangerous and where there could suddenly be a lot of fighting or problems","cn":"危机四伏的地区[形势]"},{"en":"a box containing things needed to make a flame, used in the past 〔","cn":"旧时取火用的〕火绒盒"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41tinderbox.mp3","us":"media/ldoce/hwd/ame/5/tinderbox.mp3"},"examples":[{"en":"The area is a tinderbox that could again plunge the country into civil war.","cn":"这地区是个火药桶﹐很可能再次使国家陷入内战。"}],"oxford":{"phon":"ˈtɪndəbɒks","pos":"noun","senses":[{"en":"a box containing dry material, used in the past for lighting a fire","cn":"（旧时点火用的）火绒盒，引火盒"},{"en":"a situation that is likely to become dangerous","cn":"一触即发的形势","lab":"formal","ex":{"en":"It was clearly a tinderbox situation with demonstrators likely to become violent at any moment.","cn":"这显然是一个易燃易爆的情况，示威者随时可能变得暴力。"}}]}},"tip-off":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"密报;密告","en":"A tip-off is a piece of information or a warning that you give to someone, often privately or secretly.","ex":{"en":"The man was arrested at his home after a tip-off to police from a member of the public.","cn":"在一名群众向警方举报以后，那人就在家里被逮捕了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you say or do to tell people about danger, or to tell them not to do something","cn":""},{"en":"an official warning or a piece of advice telling you to be careful","cn":""},{"en":"a warning that someone is about to do something, especially one given to the police about a crime","cn":""}]},"collocations":{"phrases":["ADJ. anonymous | phone VERB + TIP-OFF give sb | get, receive | act on Acting on a tip-off, police raided the house.","PREP. ~ about Customs officers had received a tip-off about a shipment of cocaine."]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41tip-off.mp3","us":"media/ldoce/hwd/ame/f/tip-off.mp3"},"examples":[{"en":"The man was arrested after an anonymous tip-off.","cn":"有人匿名举报后，那个人被抓了起来。"},{"en":"The arrests came after a tip-off from a member of the public.","cn":"警方接到一名老百姓的密报后﹐随即展开了逮捕行动。"}],"oxford":{"phon":"ˈtɪp ɒf","pos":"noun","senses":[{"en":"secret information that somebody gives, for example to the police, to warn them about an illegal activity that is going to happen or has happened","cn":"举报；密告；线报","ex":{"en":"The man was arrested after an anonymous tip-off.","cn":"有人匿名举报后，那个人被抓了起来。"}}]}},"tiepin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"领带别针","en":"A tie-pin is a thin narrow object with a pin on it and is used to pin a person's tie to their shirt."}]},"oxford":{"phon":"ˈtaɪpɪn","pos":"noun","senses":[{"en":"a small attractive pin that is worn on a tie to keep it in place","cn":"领带扣针；领带别针"}]}},"timpani":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"定音鼓","en":"Timpani are large drums that are played in an orchestra."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of large drums that are played in an orchestra","cn":"定音鼓"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41timpani.mp3","us":"media/ldoce/hwd/ame/d/timpani.mp3"},"oxford":{"phon":"ˈtɪmpəni","pos":"noun","senses":[{"en":"a set of large metal drums (also called kettledrums) in an orchestra","cn":"（管弦乐队的）定音鼓"}]}},"tinsel":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(圣诞节装饰用的)光片，闪光线","en":"Tinsel consists of small strips of shiny paper attached to long pieces of thread. People use tinsel as a decoration at Christmas."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"thin strings of shiny paper used as decorations, especially at Christmas 〔","cn":"尤指圣诞节期间装饰用的〕闪光纸"},{"en":"something that seems attractive but is not valuable or important","cn":"花哨而无用的东西﹐华而不实的东西"}]},"media":{"uk":"media/ldoce/hwd/bre/9/tinsel0205.mp3","us":"media/ldoce/hwd/ame/d/tinsel.mp3"},"examples":[{"en":"the tinsel and glamour of Hollywood","cn":"好莱坞的浮华和诱惑力"}],"oxford":{"phon":"ˈtɪnsl","pos":"noun","senses":[{"en":"long, thin pieces of shiny material like metal, used as decorations, especially at Christmas","cn":"（尤指圣诞节时装饰用的）光片，金属箔，金属丝","ex":{"en":"Decorate your table with tinsel and some holly.","cn":"用金属丝和一些冬青装饰你的桌子。"}}]}},"tireless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不知疲倦的;坚韧的","en":"If you describe someone or their efforts as tireless, you approve of the fact that they put a lot of hard work into something, and refuse to give up or take a rest.","ex":{"en":"He was a tireless worker for justice.","cn":"他是个为了正义不知疲倦地工作的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a lot of energy","cn":""},{"en":"energetic and ready to work hard or do a lot of things","cn":""},{"en":"very energetic and always wanting to do new things","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/tireless0205.mp3","us":"media/ldoce/hwd/ame/3/tireless.mp3"},"examples":[{"en":"a tireless campaigner for human rights","cn":"不屈不挠的人权运动参与者"},{"en":"the tireless efforts of the rescue workers","cn":"营救人员坚持不懈的努力"}],"oxford":{"phon":"ˈtaɪələs","pos":"adjective","senses":[{"en":"putting a lot of hard work and energy into something over a long period of time","cn":"不知疲倦的；不觉疲劳的；精力充沛的","ex":{"en":"a tireless campaigner for human rights","cn":"不屈不挠的人权运动参与者"}}]}},"timekeeper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"计时员;计时器","en":"A timekeeper is a person or an instrument that records or checks the time."},{"pos":"N-COUNT 可数名词","cn":"守时的人;准时的人","en":"If you say that someone is a good timekeeper, you mean that they usually arrive on time for things. If you say that they are a poor timekeeper, you mean that they are often late."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who officially records the times taken to do something, especially at a sports event 〔","cn":"尤指体育赛事中的〕计时员"},{"en":"someone who is good or bad at arriving at work at the right time","cn":"上班准时/不准时的人"},{"en":"a watch or clock that is good or bad at showing the right time","cn":"时间准/不准的钟表"}]},"media":{"uk":"media/ldoce/hwd/bre/4/timekeeper0205.mp3","us":"media/ldoce/hwd/ame/4/timekeeper.mp3"},"oxford":{"phon":"ˈtaɪmkiːpə(r)","pos":"noun","senses":[{"en":"a person who records the time that is spent doing something, for example at work or at a sports event","cn":"（工作或运动比赛等的）时间记录员，计时员"}]}},"timbre":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"音色;音质;音品","en":"The timbre of someone's voice or of a musical instrument is the particular quality of sound that it has.","ex":{"en":"His voice had a deep timbre","cn":"他嗓音低沉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of the sound made by a particular instrument or voice 〔","cn":"乐器或嗓音的〕音质﹐音品﹐音色"}]},"vocab":{"pos":"n","senses":[{"en":"Timbre is a word that describes the tone or unique quality of a sound. If you play the same note on a piano and on a guitar, each note will have its own timbre ."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41timbre.mp3","us":"media/ldoce/hwd/ame/5/timber1.mp3"},"oxford":{"phon":"ˈtæmbə(r)","pos":"noun","senses":[{"en":"the quality of sound that is produced by a particular voice or musical instrument","cn":"音质；音色；音品","ex":{"en":"the deep timbre of his voice","cn":"他的声音深沉"}}]}}});
